type SubmissionError = {
    /** The path of the offending entry, for a diagnostic a person can act on. */
    readonly path: string;
    readonly message: string;
};

type SubmissionField = {
    readonly name: string;
    readonly value: string;
};

type SubmissionTarget = {
    readonly action: string;
    readonly method: "get" | "post";
    /** Rendered as hidden inputs, in order. Empty for an endpoint needing none. */
    readonly fields: readonly SubmissionField[];
};

type SubmissionFailure = {
    /**
     * `unavailable` is "ask again later" — a token store that is down, a
     * dependency that timed out. `refused` is "not for you" — a form this
     * audience may not submit, an endpoint the deployment turned off. Separate
     * because a primitive shows different things for them, and because only one
     * of the two is worth trying again.
     */
    readonly code: "unavailable" | "refused";
    readonly detail: string;
};

type EndpointRequest = {
    /** The render request's opaque host context — audience, locale, tenant. */
    readonly context: JsonObject | undefined;
    /**
     * Aborted once the render has stopped waiting for this endpoint, which it
     * will. Pass it to whatever does the IO and the connection is let go;
     * ignore it and the page is still answered on time, but the socket is not.
     */
    readonly signal: AbortSignal | undefined;
};

interface SubmissionEndpoint {
    readonly target: (request: EndpointRequest) => Promise<Result<SubmissionTarget, SubmissionFailure>>;
}

type SubmissionUnavailable = {
    readonly reason: "no-such-endpoint" | "invalid-target" | "endpoint-threw" | SubmissionFailure["code"];
    readonly detail: string;
};

type EndpointDefinition = {
    readonly id: string;
    /**
     * One line, for the catalogue. A model choosing where a form posts has this
     * and the id to go on, and nothing else — which is the point.
     */
    readonly description: string;
    readonly endpoint: SubmissionEndpoint;
};

type EndpointEntry = {
    readonly id: string;
    readonly description: string;
    /** Total: calls, catches, validates. Never rejects. */
    readonly resolve: (context: JsonObject | undefined, signal?: AbortSignal) => Promise<Result<SubmissionTarget, SubmissionUnavailable>>;
};

type RegisteredEndpoint = EndpointEntry & {
    readonly id: EndpointId;
};

type EndpointRegistryError = {
    readonly code: "invalid-endpoint-id";
    readonly id: string;
} | {
    readonly code: "duplicate-endpoint-id";
    readonly id: string;
};

interface EndpointRegistry {
    readonly endpoint: (id: EndpointId) => RegisteredEndpoint | undefined;
    /** In registration order, so a catalogue reads predictably. */
    readonly endpoints: readonly RegisteredEndpoint[];
}

type PlannedSubmission = {
    readonly nodeId: NodeId;
    readonly to: EndpointId;
};

type SubmissionProblem = {
    readonly nodeId: NodeId;
    readonly error: SubmissionError;
};

type SubmissionPlan = {
    /** Deduplicated endpoint ids, in first-encountered order. */
    readonly endpoints: readonly EndpointId[];
    readonly submissions: readonly PlannedSubmission[];
    readonly problems: readonly SubmissionProblem[];
};

type SubmissionOutcome = {
    readonly status: "ready";
    readonly target: SubmissionTarget;
} | {
    readonly status: "unavailable";
    readonly unavailable: SubmissionUnavailable;
};

type NodeSubmissionProblem = {
    readonly kind: "misdeclared";
    readonly error: SubmissionError;
} | {
    readonly kind: "unavailable";
    readonly to: EndpointId;
    readonly unavailable: SubmissionUnavailable;
};

interface SubmissionResolution {
    /**
     * `undefined` for the overwhelming majority of nodes, which declare none — and
     * for that reason it is not a way to say "I have no target for you". A node that
     * declares `loom:submit` and gets `undefined` with no problem beside it earns a
     * `submit-unresolved` diagnostic from the walk, for the reason the data seam's
     * twin gives at length.
     */
    readonly lookup: (nodeId: NodeId) => SubmissionOutcome | undefined;
    readonly problemsFor: (nodeId: NodeId) => readonly NodeSubmissionProblem[];
}

type ResolveSubmissionsOptions = {
    readonly registry: EndpointRegistry;
    /** Passed through to every endpoint — the render request's host context. */
    readonly context?: JsonObject;
    /**
     * How long any one endpoint is given, each independently of the others.
     * Defaults to `DEFAULT_ENDPOINT_CEILING_MS`; there is no way to wait forever
     *.
     */
    readonly ceilingMs?: number;
};

type ThemeVariableOptions = {
    /**
     * Whether the two ramps may read the width they are rendered at.
     *
     * `"fluid"` is the default and is what a page in a browser wants: a declared
     * step is a maximum, reached at `48rem` and held above it, so a tree built
     * for a laptop is legible on a phone without the tree knowing a phone exists
     *. `"fixed"` emits the pack's numbers as the plain pixel lengths they
     * were before that record, for a medium with no cascade to substitute — see
     * `ramp.ts` for why a `clamp()` is worse than a pixel there.
     */
    readonly ramp?: RampMode;
};

type TextPairing = {
    readonly foreground: PaletteSlot;
    readonly background: PaletteSlot;
    readonly basis: PairingBasis;
    /** Where it happens, so a failure names a page rather than two slot ids. */
    readonly where: string;
};

type MeasuredPairing = {
    readonly pairing: TextPairing;
    readonly ratio: number;
    readonly meets: boolean;
};

type UnmeasuredPairing = {
    readonly pairing: TextPairing;
    readonly foreground: string;
    readonly background: string;
};

type HueSpec = {
    /** 0–360. */
    readonly hue: number;
    /** 0–100. Zero gives a neutral grey, which is how the monochrome palettes are built. */
    readonly saturation: number;
};

type PaletteSpec = {
    readonly id: string;
    readonly name: string;
    readonly description: string;
    readonly mode: PaletteMode;
    /** The page itself. Its hue tints every neutral, which is what stops a palette looking like grey with colour on top. */
    readonly canvas: HueSpec;
    /** The colour that carries meaning as text. Darkened, or lightened, until it can. */
    readonly accent: HueSpec;
    /** The second colour. Never carries text, so it keeps its chroma — this is what `loom.hero`'s aurora paints. */
    readonly secondary: HueSpec;
    /**
     * Lightness of the canvas, the surface behind a card, and the muted well, in
     * that order. Defaults suit most palettes; a deeper dark mode or a warmer
     * paper is where you would change them.
     */
    readonly levels?: readonly [number, number, number];
    /**
     * Forces `accent` to the end of the range rather than to the lightest value
     * that clears the bar. A palette with no chroma has nothing to solve for, and
     * solving anyway leaves a mid-grey primary button that reads as a disabled
     * one.
     */
    readonly extremeAccent?: boolean;
};

const derivePaletteChecked: (spec: PaletteSpec) => {
    readonly palette: Palette;
    readonly clean: boolean;
}

type Scrim = {
    readonly ground: PaletteSlot;
    readonly foreground: PaletteSlot;
    /** Of the ground. How much this wash can actually darken. */
    readonly luminance: number;
    /** Of the pair, which is the palette's own body-copy ratio. */
    readonly ratio: number;
    /** Whether the ground is under `SCRIM_DARK_CEILING`. */
    readonly darkens: boolean;
};

type PaletteMeasures = {
    readonly palette: ThemeId;
    /**
     * Chroma per slot, normalised, for the slots that carry colour. A slot whose
     * colour could not be measured is **absent** rather than zero: zero is a real
     * answer meaning grey, and `graphite`'s accent really is 0.000.
     */
    readonly chroma: Readonly<Partial<Record<PaletteSlot, number>>>;
    readonly scrim: Scrim | undefined;
    /**
     * Which way round the palette is, and `undefined` on the same terms `scrim`
     * is: a pair this cannot read is reported as unavailable rather than guessed.
     */
    readonly scheme: PaletteScheme | undefined;
};

type ThemeError = {
    readonly code: "unknown-palette";
    readonly id: string;
    readonly available: readonly string[];
} | {
    readonly code: "unknown-font-pack";
    readonly id: string;
    readonly available: readonly string[];
} | {
    readonly code: "unknown-style-preset";
    readonly id: string;
    readonly available: readonly string[];
