type PartAction = {
    readonly nodeId: NodeId;
    readonly type: PrimitiveType;
    /** What part it plays, or `null` where its type declared none. */
    readonly role: PrimitiveRole | null;
    /** 0 at the root. */
    readonly depth: number;
    /** null at the root. */
    readonly parentId: NodeId | null;
    /**
     * What this window can say about whether readers acted on this part.
     *
     * Per part, except for the one rule that is a property of the window: in an
     * {@link PageAction.unwalked} window nothing is `untouched`, because the
     * nought that member is read off is the ancestry missing.
     */
    readonly standing: ActionStanding;
    /**
     * Whether any element part of this revision names it as a parent.
     *
     * The structural fact that decides whether a share is a measurement. Taken
     * off the tree the reading was built from, so it is a property of the page
     * and not of the window — a part with children keeps them in a window nobody
     * read.
     */
    readonly bearsParts: boolean;
    /** Distinct page views that reported it coming into view, or `undefined` where no row named it. */
    readonly reached: number | undefined;
    /**
     * Distinct page views in which a reader used something strictly inside it
     *, or `undefined` where no row named it.
     *
     * `0` on a leaf is a filing rule and not a measurement; {@link share} is what
     * is withheld on account of it, and this number is passed through unaltered
     * because a caller looking at one part's row should see what the store holds.
     */
    readonly within: number | undefined;
    /**
     * `within ÷ reached`, in `[0, 1]`, or `undefined`.
     *
     * Withheld where the part bears no element parts, where no row named it, and
     * where its `reached` is 0 — which are the three states the standing of
     * `unknown` covers, so a withheld share and an unknown standing are the same
     * fact said twice and never disagree.
     *
     * **And withheld on every part of an {@link PageAction.unwalked} window**,
     * whatever its standing, because this is the one figure here built out of
     * `engaged` and `engaged` is the one counter the ancestry walk feeds.
     * So an unknown standing still always means a withheld share, and in that one
     * window a withheld share no longer means an unknown standing: a band with
     * opens of its own is `acted` on evidence that needed no walk, and has no
     * share all the same.
     *
     * Both terms are distinct view counts off the same row, which is why this is
     * the figure on a card that can be trusted while the counts beside it are
     * generous by the straddle, measured since the door counted openings
     *. It is deliberately
     * **not** divided by the page views counted at the door: `opened` and
     * `engaged` are written in different places and their ratio can honestly
     * exceed 1, which is a refusal made once already and it still stands.
     */
    readonly share: number | undefined;
    /**
     * Presses, opens, closes and submissions filed against this part itself,
     * added.
     *
     * **Occurrences, never readers.** Four counters go in because they are four
     * ways of using a thing and a caller asking *was this used* wants one number;
     * the four are on {@link PartAction.counts} apart for a caller that wants to
     * tell a press from a dismissal. `0` where no row named it, because *nothing
     * happened* and *nothing was reported* are told apart by the standing rather
     * than by making every arithmetic consumer handle an absence.
     */
    readonly uses: number;
    /** The four occurrence counters, kept apart. `0` each where no row named it. */
    readonly counts: {
        readonly activations: number;
        readonly opens: number;
        readonly closes: number;
        readonly completions: number;
    };
    /**
     * `uses ÷ reached`, or `undefined` where nothing was used or nobody reached
     * it.
     *
     * **An intensity and not a rate.** It may exceed 1, and above 1 it says
     * readers used this part more than once each rather than that more readers
     * used it than reached it. Withheld at `uses` of 0 rather than published as a
     * nought, because a nought here is the ordinary state of every heading on the
     * page and {@link uses} already says it.
     */
    readonly usesPerReader: number | undefined;
    /**
     * `closes ÷ opens`, or `undefined` where nothing was opened.
     *
     * *Readers open this ask and shut it again nine times in ten* — two
     * occurrence counts off one row, so the straddle divides out of it the way it
     * does out of {@link share}.
     *
     * **Uncapped on purpose.** Above 1 means closes the page's own opens cannot
     * account for, which is a disclosure a revision renders already open: the
     * reader shuts something they never opened. Capping it would hide the one
     * state it can diagnose, and a clause nothing can falsify is not a safeguard
     *.
     */
    readonly shutAgain: number | undefined;
};

type ComparedAction = {
    readonly nodeId: NodeId;
    /** The later revision's type, which is the page somebody is looking at. */
    readonly type: PrimitiveType;
    /** The later revision's role, or `null` where its type declared none. */
    readonly role: PrimitiveRole | null;
    /** The whole of what the earlier window said about it. */
    readonly was: PartAction;
    /** The whole of what the later window said about it. */
    readonly now: PartAction;
    readonly movement: ActionMovement;
    /** What the change did to whether a share of this part is measurable at all. */
    readonly inside: InsideMovement;
    /**
     * `now.share ÷ was.share`, with the reason named where there is no quotient
     *.
     *
     * **The one ratio here that is sound across two windows.** Each side's share
     * is two distinct view counts off one row, so each window's straddle
     * has very nearly divided out before the two sides meet — the cancellation a
     * fall between two siblings rests on, and the reason a ratio of the
     * counts themselves is refused by this module and not published anywhere on
     * this type.
     *
     * Nought on the earlier side is `from-nothing` rather than infinity: *nobody
     * acted here and now somebody does* is {@link movement}'s answer and the two
     * sides', and a quotient is a figure a surface divides and ranks by.
     *
     * It holds a number **only where {@link inside} is `kept`**, which falls out
     * of the two sides' shares being withheld on a leaf and is not a separate
     * rule: a ratio across a part whose shape changed would be a ratio of two
     * different measurements. Those are `unmeasured`, and {@link inside} says
     * which direction the shape moved in.
     *
     * `unmeasured` across an {@link ActionChangeSilence} of `unwalked` by the
     * same route: that window has no share to give.
     */
    readonly shareRatio: Ratio;
    /**
     * `now.usesPerReader ÷ was.usesPerReader`, with a nought a side withheld
     * restored first.
     *
     * Occurrences per reader on each side, so each term has its own window's
     * straddle divided out of it and the ratio stands. **An intensity and not a
     * rate** on both sides, so this is how much more each reader used a
     * part and never how many more readers did.
     *
     * A side that reached readers and was used by none of them counts as a nought
     * here, where the reading itself withholds the figure: a part nobody touched
     * and four presses a reader now is `from-nothing`, and a part readers used
     * and have stopped using is a quotient of nought. `unmeasured` is a side with
     * no readers to divide by, which is the one state neither window measured.
     *
     * The figure here that survives `unwalked`, because the four occurrence
     * counters are filed against the part a reader used and need no ancestry.
     */
    readonly usesRatio: Ratio;
};

type ActionChange = {
    /** The earlier reading's tree. The two agree unless `silence` is `different-trees`. */
    readonly treeId: TreeId;
    readonly revisions: {
        readonly was: number;
        readonly now: number;
    };
    /**
     * The audience each side was of, where its reading named one.
     *
     * As `ReadingChange.audiences` carries it, and for the same reason: a `null`
     * on either side is why an unprovable pair of populations is compared rather
     * than refused.
     */
    readonly audiences: ComparedAudiences;
    /** The two readings of what readers did that this comparison is made of. */
    readonly readings: {
        readonly was: PageAction;
        readonly now: PageAction;
    };
    /**
     * Every part both revisions have that a row named on either side, in the
     * **later** reading order.
     *
     * The later order because that is the page somebody is looking at. A part no
     * row named on either side is left out: nothing in either window reported it,
     * so a row for it could only ever read `unknown` and would make
     * {@link movements} a count of parts nobody measured. {@link insides} is
     * therefore a census of the compared parts and not of the tree.
     */
    readonly compared: readonly ComparedAction[];
    /**
     * Parts only the later revision has, as the later window read them, in its
     * reading order.
     *
     * A census with readers in it rather than an exact one, unlike the census of
     * the words a change wrote: a part that did not exist before has to be
     * reached now for anything to be said about it. *The change added an ask and
     * nobody has opened it* is the row worth looking at.
     */
    readonly added: readonly PartAction[];
    /** Parts only the earlier revision had, as the earlier window read them, in its reading order. */
    readonly removed: readonly PartAction[];
    /** Compared parts by what happened to the standing. The five add to {@link compared}'s length. */
    readonly movements: Readonly<Record<ActionMovement, number>>;
    /** Compared parts by what the change did to their shape. The four add to {@link compared}'s length. */
    readonly insides: Readonly<Record<InsideMovement, number>>;
    /**
     * The root, compared against itself across the two revisions.
     *
     * *Three in ten readers did something on this page and now four in ten do* —
     * the page's one headcount figure, and a row rather than an addition: every
     * action is strictly inside the root, so summing `within` across parts would
     * charge one reader once per level they acted inside. That is why
     * there is **no page-level total of readers who acted** here or anywhere, and
     * this stands in for one.
     *
     * Kept out of the rankings below, because its subtree is every part it would
     * outrank — the rule a pace comparison and a fall between two siblings both
     * follow.
     *
     * `null` where either revision's root is not an element, or where no row named
     * it on either side.
     */
    readonly whole: ComparedAction | null;
    readonly mostTakenUp: ComparedAction | null;
    /** The ask the change lost, on the same terms. */
    readonly mostAbandoned: ComparedAction | null;
    /**
     * The parts readers reached and did nothing in, before and after — most
     * reached now first, then in the later reading order.
     *
     * The list a person can act on without reading anything else, and the one
     * ranking here about where a change did **not** land. The root is left out as
     * it is left out of every ranking here; {@link whole} carries it.
     * `still-untouched` only: a part whose standing is `unknown` on either side is
     * in {@link movements} where it can be seen and not acted on, because putting
     * it here would turn *nothing can be said* into *readers are ignoring this*.
     */
    readonly stillUntouched: readonly ComparedAction[];
    /** Why there is no comparison of the reading, or `null` where there is one. */
    readonly silence: ActionChangeSilence | null;
};

type SideOfAudience = {
    /** `null` or absent where nothing recorded which audience the window was of. */
    readonly audienceId?: AudienceId | null;
};

type ReadingOfAudience = SideOfAudience & {
    readonly treeId: TreeId;
    readonly revision: number;
};

type AudienceScope =
/**
 * One population: the audience asked for, or the only one the window named.
 *
 * A window naming one audience needs no caller to say so, and an audience
 * asked for scopes the reading whether or not the window holds others — the
 * rest of it is that page's other form, counted apart and not read.
 */
{
    readonly reading: "one";
    readonly audienceId: AudienceId;
    /** What the window named, which is not what was asked for. */
    readonly audiences: readonly AudienceId[];
}
/**
 * Nothing in the window named an audience, so it is one population by
 * construction and is read whole.
 *
 * Every window written before the column existed, and every window a
 * caller built by hand. Calling it `aud_everyone` would assert what no row
 * said, which is the distinction {@link MaybeAudienceScoped} exists for.
 */
 | {
    readonly reading: "unlabelled";
    readonly audienceId: null;
    readonly audiences: readonly [];
}
/**
 * Two or more forms, and the asking named none of them.
 *
 * Read as **neither**. The other two answers available are summing two
 * populations and picking one of them by the caller's array order, and the
 * second is the fault this type exists to make unwritable. Summing is a
 * decision per counter rather than a default: arrivals at the door are
 * counted once per page view and therefore add, and a distinct
 * count filed against a node does not.
 */
 | {
    readonly reading: "mixed";
    readonly audienceId: null;
    readonly audiences: readonly AudienceId[];
};

type ReadOfAudience = {
    readonly audienceId: AudienceId | null;
    readonly audiences: readonly AudienceId[];
};

type AudienceWindow<R> = {
    readonly audience: AudienceId;
    readonly rows: readonly R[];
};

type PageForm = {
    readonly treeId: TreeId;
    readonly audienceId: AudienceId | null;
};

type ComparedAudiences = {
    readonly was: AudienceId | null;
    readonly now: AudienceId | null;
};

type ComparedPopulations = {
    /** The audiences the earlier window's forms named. `[]` where none did. */
    readonly was: readonly AudienceId[];
    /** The audiences the later window's forms named, by the same rule. */
    readonly now: readonly AudienceId[];
};

type SideOfForm = ReadOfAudience & {
    readonly treeId: TreeId;
    readonly revision: number;
};

type FormPair<R> = {
    readonly pairing: "paired";
    /** The side whose audience id sorts lower. */
    readonly one: R;
    readonly other: R;
    /** The two names, already in the same order as the two sides. */
    readonly audiences: {
        readonly one: AudienceId;
        readonly other: AudienceId;
    };
} | {
    readonly pairing: "refused";
    /** The lower-sorting side, or the first argument where no pair of names stands. */
    readonly one: R;
    readonly other: R;
    readonly refusal: FormPairRefusal;
};

type VisibilityObserver = {
    readonly observe: (element: Element) => void;
    readonly disconnect: () => void;
};

type VisibilityEntry = {
    readonly target: Element;
    readonly visible: boolean;
};

type ReaderSignalTypes = readonly string[] | {
    readonly [Kind in ReaderSignalKind]?: readonly string[];
};

type ReaderSignalOptions = {
    /** Called with every batch. A throw or rejection here is contained and never reaches the page. */
    readonly send?: (batch: ReaderSignalBatch) => void | Promise<void>;
    /** Which kinds to broadcast. Every kind when absent. */
    readonly kinds?: readonly ReaderSignalKind[];
    /**
     * Which primitive types to broadcast about. Every addressed type when absent.
     *
     * A list applies to every kind. An object sets it per kind — time on screen
     * for sections, activations for links — and a kind it does not name is
     * reported for every type, exactly as if `types` were absent for that kind.
     * Whether a kind is reported at all is still `kinds`.
     */
    readonly types?: ReaderSignalTypes;
    /** How often a batch is delivered. Five seconds when absent. */
    readonly flushEveryMs?: number;
    /**
     * How the broadcaster learns what is on screen. The browser's
     * `IntersectionObserver` when absent; a test passes its own.
     */
    readonly observeVisibility?: ObserveVisibility;
    /**
     * Whether a delegated signal carries the addressed nodes it happened inside.
     * On when absent.
     *
     * `activated` and `disclosed` are filed against the control a reader aimed
     * at, which is an addressed node of its own — so without the ancestry a
     * deployment can report which button was pressed and never which region it
     * was in. Off is for a host that reports on controls only and would rather
     * not carry the walk in every batch.
     */
    readonly within?: boolean;
    /** The clock. `Date.now` when absent. */
    readonly now?: () => number;
    /**
     * Where the view key's randomness comes from. The browser's
     * `crypto.getRandomValues` when absent; a test passes its own so it can name
     * the key it expects.
     */
    readonly random?: RandomBytes;
};

type ReaderSignalBroadcast = {
    /** Deliver whatever has been gathered, now. */
    readonly flush: () => void;
    /** Deliver what is left and stop observing. Safe to call twice. */
    readonly stop: () => void;
};

type ReaderSignalBroadcastError = {
    /** The root carries no tree id or revision — the page was not rendered with `addressed: true`. */
    readonly code: "unaddressed";
    readonly detail: string;
};

type StopSide = {
    /** Views that reached the first of the pair, which is the denominator of `share`. */
    readonly reached: number;
    /** Views that reached the first and not the second. Zero where none did. */
    readonly lost: number;
    /** `lost ÷ reached`, in `[0, 1]`. Zero is a pair nobody stopped at. */
    readonly share: number;
};

type ComparedStop = {
    /** The part they reached. */
    readonly after: NodeId;
    /** The next part in the run, which fewer reached. */
    readonly before: NodeId;
    /** The parent whose run they are both steps of, which is the same node in both readings. */
    readonly parentId: NodeId;
    readonly was: StopSide;
    readonly now: StopSide;
    /**
     * `was.share − now.share`: the share of readers that no longer stop here.
     *
     * **Positive is better**, because a stop is a loss, and
     * {@link ComparedStop.readersKept} carries the same sign for the same reason.
     * A screen that subtracted the other way round would have one of its two
     * figures pointing the wrong way, which is the defect a reviewer cannot see.
     */
    readonly improvement: number;
    /**
     * The smallest share one reader could move, on whichever side counted fewer.
     *
     * `1 ÷ min(was.reached, now.reached)`. It is the resolution of the comparison
     * and not a confidence interval: two readers out of three against one out of
     * two is a third of a share point apart and is two readers, and no amount of
     * arithmetic makes it more than that.
     */
    readonly resolution: number;
    /**
     * Whether `improvement` is at least one reader's worth on the coarser side.
     *
     * False is *nothing happened here that a reader did*, and it is the field that
     * keeps a sparsely-read page off the top of a screen. Evaluated in integers
     * rather than by comparing two divisions, so a rounding error never decides
     * whether a reader exists.
     */
    readonly beyondOneReader: boolean;
    /**
     * `improvement × now.reached`: the readers the change no longer loses here, at
     * the volume the page has now.
     *
     * The ranking key, and it ranks by readers rather than by share for the same
     * reason a fall does — a stop two readers out of three abandoned is a
     * worse rate and a smaller problem than one four hundred out of a thousand
     * did. Not rounded, because it is a rate times a count and a magnitude rather
     * than a census, and **never added across stops**: one reader is in every stop
     * they walked past.
     */
    readonly readersKept: number;
};

type IncomparablePair = {
    readonly after: NodeId;
    readonly before: NodeId;
    readonly parentId: NodeId;
    /** Which reading this pair is from, and therefore which reading `reached` and `share` are off. */
    readonly side: "was" | "now";
    readonly fate: PairFate;
    readonly reached: number;
    readonly share: number;
};

type PartsChanged = {
    /** Element nodes in both revisions, {@link PartsChanged.moved} among them. */
    readonly shared: number;
    /** In the later revision and not the earlier one, in reading order. */
    readonly added: readonly NodeId[];
    /** In the earlier revision and not the later one, in reading order. */
    readonly removed: readonly NodeId[];
    /** Shared parts whose parent is a different node, in reading order. */
    readonly moved: readonly NodeId[];
    /**
     * Shared parts whose own words are not the words they were, in reading order.
     *
     * **A floor and not a count.** A part's words are the props its type declared
     * as copy and its direct text children, so a part whose type declares
     * nothing has no words to compare and a rewording of it is invisible here.
     * {@link PartsChanged.unreadable} is how many parts that is, which is what
     * stops the floor from reading as a total.
     */
    readonly reworded: readonly NodeId[];
    /**
     * Shared parts whose words were the same as far as this reading could see, and
     * where something about them went unread on one side or the other.
     *
     * *Nobody has said whether these props are words* is a different answer from
     * *these words did not change*, and keeping them apart is the bargain `copy`
     * was declared under and the join carried into a reading.
     */
    readonly unreadable: number;
};

type ReadingChange = {
    /** The earlier reading's tree. The two agree unless `silence` is `different-trees`. */
    readonly treeId: TreeId;
    readonly revisions: {
        readonly was: number;
        readonly now: number;
    };
    /**
     * The audience each side was of, where its reading named one.
     *
     * Carried under every silence and under none. A `null` on either side is why
     * a pair of two populations can still be compared here: it is unprovable
     * rather than proven alike, and a surface saying *compared across a window
     * that named no audience* needs the field to say it.
     */
    readonly audiences: ComparedAudiences;
    /**
     * The two progress readings this comparison is made of.
     *
     * Carried rather than left to the caller, because deriving them twice is how
     * two screens come to disagree — and because the headline of each side is
     * already on them: a consumer that wants *the steepest fall before, and what
     * happened to it* takes `progress.was.steepest` and finds that pair in
     * {@link ReadingChange.stops} or {@link ReadingChange.incomparable} by its two
     * node ids.
     */
    readonly progress: {
        readonly was: ReadingProgress;
        readonly now: ReadingProgress;
    };
    readonly parts: PartsChanged;
    /** Every pair both readings could measure, in the earlier reading's reading order. */
    readonly stops: readonly ComparedStop[];
    /** Every pair only one of them could, each once, with the reason. */
    readonly incomparable: readonly IncomparablePair[];
    /**
     * The pair the change keeps most readers at, among those beyond one reader.
     *
     * Null where no pair improved by more than a reader, which includes every page
     * the change did not help.
     */
    readonly mostKept: ComparedStop | null;
    /** The pair it loses most readers at, on the same terms. Null where none worsened. */
    readonly mostLost: ComparedStop | null;
    /** Why nothing was compared, or `null` where something was. */
    readonly silence: ChangeSilence | null;
};

type CollectionRequest = {
    readonly windowMs?: number;
    /**
     * The funnels this deployment asks about. Absent means none — a pair is a
     * question somebody wrote down, and rollup does not invent questions.
     *
     * A pair added later applies to windows collected after it, never to the ones
     * already folded, because the batches those answers came from are gone. That
     * is the price of aggregates being the durable artefact and it is worth
     * knowing before a deployment waits a day for a number it will not get.
     */
    readonly pairs?: readonly FunnelPair[];
    readonly clock?: Clock;
    readonly scanLimit?: number;
};

type CollectionPlan = {
    /** Old enough to count, in ascending `seq`. */
    readonly ripe: readonly ReceivedBatch[];
    /** The position to forget below, once the counters are durable. `null` when nothing is ripe. */
    readonly before: number | null;
    /** Seen by this scan and too young. A floor rather than a total — the scan stops at the first. */
    readonly waiting: number;
};

type CollectionSummary = {
    readonly counted: number;
    readonly tallies: number;
    readonly funnels: number;
    /** Distinct page views the window held. */
    readonly views: number;
    /**
     * Batches that carried no view key, whose occurrences counted and whose views
     * did not. A rate shown without saying which denominator it used is the
     * failure mode here, so the number travels with the run that produced it.
     */
    readonly uncorrelated: number;
    /**
     * Of the batches counted, how many were a repeat of one already folded in
     * this window and were therefore folded once (`rollup.ts`).
     *
     * A subset of `counted` rather than a number beside it: every one of them was
     * read from the buffer and is forgotten with the rest. Non-zero every run is
     * a sender retrying deliveries it already made, which is worth finding — and
     * the figure is in the run's outcome rather than in a stored row because a
     * fold's own numbers are not durable, only the counters it produced are.
     */
    readonly redelivered: number;
};

type CollectionOutcome = {
    readonly outcome: "collected";
    readonly summary: CollectionSummary;
    /** Rows the buffer removed. Below `counted` only if something else pruned first. */
    readonly removed: number;
    /** The scan filled its limit with ripe batches, so another run has work now. */
    readonly more: boolean;
}
/** Nothing is old enough yet, which is the ordinary answer on a quiet deployment. */
 | {
    readonly outcome: "nothing-ripe";
    readonly waiting: number;
}
/**
 * The counters took the window and the buffer would not drop it.
 *
 * Its own outcome because it is the one state that gets worse if it is
 * ignored: the batches are durable in the counters and still in the buffer,
 * so the next run counts them again. An operator seeing this prunes below the
 * reported position by hand, or fixes the buffer before the next run.
 */
 | {
    readonly outcome: "counted-not-forgotten";
    readonly summary: CollectionSummary;
    readonly before: number;
    readonly error: ReaderSignalStoreError;
}
/** The window was not usable. Nothing was read, counted or deleted. */
 | {
    readonly outcome: "refused";
    readonly reason: string;
}
/** Read or write failed before anything became durable. Nothing was deleted. */
 | {
    readonly outcome: "unavailable";
    readonly error: ReaderSignalStoreError;
};

type Passage = {
    readonly nodeId: NodeId;
    readonly type: PrimitiveType;
    /** What part it plays, or `null` where its type declared none. */
    readonly role: PrimitiveRole | null;
    /** 0 at the root. */
    readonly depth: number;
    /** Carried through from the part, so a passage and a part say the same thing. */
    readonly standing: PartStanding;
    /** Distinct page views that reported the part coming into view; `0` where no row named it. */
    readonly readers: number;
    /**
     * The words themselves, in reading order, exactly as the page says them.
     *
     * **Its own, never its subtree's**, so the text of two passages may be
     * concatenated and no sentence is read twice.
     */
    readonly text: readonly string[];
    /** {@link text}, counted. */
    readonly words: number;
    /**
     * Whether this passage is short of words it cannot see.
     *
     * True where the part's type declared no `copy`, or declared a prop holding
     * something that is not a string. The words it does hold are still its
     * own; what is not knowable is whether there are more.
     */
    readonly floored: boolean;
};

type RoleCopy = {
    /** `null` is the row for parts whose type declared no role. */
    readonly role: PrimitiveRole | null;
    /** Parts of this role that say something, which is the rule {@link CopyReading.passages} applies. */
    readonly passages: number;
    readonly words: number;
    /**
     * Words by the standing of the part saying them. The three add to
     * {@link words}.
     */
    readonly wordsByStanding: Readonly<Record<PartStanding, number>>;
    /**
     * This role's words in parts the window can speak for, which is the
     * denominator of {@link share}.
     *
     * Addable across roles, like {@link words} and for the same reason. The rest
     * of the role's words are `wordsByStanding.unknown`, which is the mass
     * outside the question rather than words nobody read.
     */
    readonly spoken: number;
    /**
     * The share of this role's **spoken-for** words at least one reader reached.
     * `null` where the window can speak for none of them.
     *
     * Addable across roles — unlike every view count on a `RoleReading`, which is
     * absent there because distinctness cannot be added. Words can: they
     * are a property of the page rather than of the readers.
     */
    readonly share: number | null;
    /** Passages of this role whose words are a floor. */
    readonly floored: number;
};

type PassageMovement =
/** Reached on both sides. */
"held"
/** Nobody reached it and now somebody does, which is the sentence a change is made for. */
 | "gained"
/** Somebody reached it and now nobody does. */
 | "lost"
/** Nobody reached it on either side — the words a change did not fix. */
 | "unread"
/**
 * One side cannot be spoken for.
 *
 * Its window held no views at all, or the passage reported something other
 * than coming into view, so `skipped` would be a claim nobody made.
 */
 | "unknown";

type PassageSide = {
    readonly standing: PartStanding;
    /** Distinct page views that reported the part coming into view; `0` where no row named it. */
    readonly readers: number;
    /** That side's page-view floor, carried through so the share below can be checked. */
    readonly views: number;
    /**
     * {@link readers} over {@link views}, and `null` where the window held none.
     *
     * A ceiling on the share of that window's readers who reached the passage:
     * `reached` is generous by the page views that straddled a rollup window
     * and `views` is a floor on the page views there were, so the
     * numerator leans up and the denominator leans down. It is the figure the two
     * sides are compared on, because the same inflation is in both terms of each
     * side and has very nearly divided out before the sides meet.
     *
     * Above 1 is the input `inconsistent` names. It is not clamped: a figure cut
     * to fit its own ceiling is a fault made undrawable rather than visible.
     */
    readonly reach: number | null;
};

type ComparedPassage = {
    readonly nodeId: NodeId;
    readonly type: PrimitiveType;
    readonly role: PrimitiveRole | null;
    /** The words, the same number on both sides because they are the same words. */
    readonly words: number;
    /** The text itself, so a passage can be quoted back without a second join. */
    readonly text: readonly string[];
    /**
     * Whether either side's part declares no `copy`, so {@link words} is a floor.
     *
     * The visible words are the same on both sides; what a floor withholds is
     * whether there are more. A side may be floored where the other is not, when
     * a prop a type does not declare holds something on one revision and nothing
     * on the other — so this is either side, and the figures it qualifies are
     * qualified for both.
     */
    readonly floored: boolean;
    readonly was: PassageSide;
    readonly now: PassageSide;
    readonly movement: PassageMovement;
    /**
     * The words this passage newly put in front of the average reader:
     * `words × (now.reach − was.reach)`.
     *
     * Negative where readers lost ground, and `null` where either side held no
     * views **or either side's standing is `unknown`** — a reach of nought
     * that is a missing counter is not a reader who did not arrive, and
     * subtracting against it would sign the other side's whole reach as something
     * the change did. It adds across passages — a part's own words partition the
     * page exactly once — and the sum is {@link CopyChange.typical}'s
     * `change`, over the same spoken-for passages.
     *
     * A floor on {@link words} scales it toward zero and cannot change its sign,
     * which is why it is published where the page total is withheld.
     */
    readonly gain: number | null;
};

type RewordedPassage = {
    readonly nodeId: NodeId;
    readonly type: PrimitiveType;
    readonly role: PrimitiveRole | null;
    /** The two word counts, which is why there is no single one. */
    readonly words: {
        readonly was: number;
        readonly now: number;
    };
    /** Whether either side declares no `copy`, so its word count is a floor. */
    readonly floored: boolean;
    readonly was: PassageSide;
    readonly now: PassageSide;
    readonly movement: PassageMovement;
};

type WordsWritten = {
    /**
     * Words both revisions say, word for word — the universe every reader figure
     * here is about.
     */
    readonly carried: number;
    /** Words only the later revision says. */
    readonly added: number;
    /**
     * {@link added}, by what the later window said about reaching them. The three
     * add to {@link added}.
     *
     * *Of the three hundred words this change wrote, forty have been reached.* It
     * is the one figure here that is about words nobody could have read before,
     * so it has no comparison and needs none.
     */
    readonly addedByStanding: Readonly<Record<PartStanding, number>>;
    /** Words only the earlier revision says. */
    readonly removed: number;
    /**
     * {@link removed}, by what the earlier window said about reaching them. The
     * three add to {@link removed}.
     *
     * *The change took two hundred words away and nobody had reached a hundred and
     * eighty of them* is a change that was right, and the opposite reading of the
     * same row is the one worth stopping for.
     */
    readonly removedByStanding: Readonly<Record<PartStanding, number>>;
    /** Words of passages both revisions have and neither says the same way. */
    readonly reworded: {
        readonly was: number;
        readonly now: number;
    };
};

type WordCount = {
    readonly was: number;
    readonly now: number;
    readonly change: number;
};

type CopyChange = {
    /** The earlier reading's tree. The two agree unless `silence` is `different-trees`. */
    readonly treeId: TreeId;
    readonly revisions: {
        readonly was: number;
        readonly now: number;
    };
    /**
     * The audience each side was of, where its reading named one.
     *
     * As `ReadingChange.audiences` carries it, and for the same reason: a `null`
     * on either side is why an unprovable pair of populations is compared rather
     * than refused.
     */
    readonly audiences: ComparedAudiences;
    /** The two copy readings this comparison is made of. */
    readonly readings: {
        readonly was: CopyReading;
        readonly now: CopyReading;
    };
    /**
     * Every word each revision says, counted once, and the difference.
     *
     * Exact on both sides and comparable without qualification, which no other
     * pair of figures in this subsystem is: a page's words are a property of its
     * tree and no reader is in them.
     */
    readonly words: WordCount;
    /** The census of what the change wrote, with no reader in it. */
    readonly wrote: WordsWritten;
    /**
     * Every passage both revisions say identically, in the **later** reading's
     * reading order.
     *
     * The later order because that is the page somebody is looking at, and a
     * passage's place in it is where they would find it. A before-and-after of
     * where reading stops orders its pairs by the earlier reading instead,
     * because a pair is a position by construction and cannot survive being moved;
     * a passage can, so the two modules order their rows differently on purpose.
     */
    readonly compared: readonly ComparedPassage[];
    /** Every passage both revisions have and neither says the same way, in the later order. */
    readonly reworded: readonly RewordedPassage[];
    /** Every passage only the later revision has, in its reading order. */
    readonly added: readonly Passage[];
    /** Every passage only the earlier revision had, in the earlier reading order. */
    readonly removed: readonly Passage[];
    /**
     * Carried words by what happened to the reading of them. The five add to
     * {@link WordsWritten.carried}.
     */
    readonly wordsByMovement: Readonly<Record<PassageMovement, number>>;
    /**
     * Carried passages by the same. The five add to {@link compared}'s length.
     *
     * Published beside the word totals because a count of passages **survives a
     * floor** where a count of words does not: a part that declares no `copy` is
     * one part whatever it is hiding. A surface that has to be right about
     * direction under a floor reads this row.
     */
    readonly passagesByMovement: Readonly<Record<PassageMovement, number>>;
    /** Carried passages whose words are a floor, which is what `floored` counts. */
    readonly floored: number;
    /**
     * The carried passages nobody reached on either side, most words first and
     * then in the later reading order.
     *
     * The words a change did not fix, which is the list a person can act on
     * without reading anything else. Ranked by words for the reason one window's
     * reading ranks them: the passage nobody saw that costs the page most is
     * the long one, not the first one.
     *
     * `unread` only. A passage whose standing is `unknown` on either side is in
     * {@link wordsByMovement} where it can be seen and not acted on, because
     * putting it here would turn *nothing can be said* into *nobody read this*.
     */
    readonly stillUnseen: readonly ComparedPassage[];
    /**
     * The carried words the average reader got to, before and after. `null` where
     * {@link silence} says why not.
     *
     * Each side is `Σ(readers × words) ÷ views` over the carried passages **both
     * windows can speak for** — the same arithmetic as `CopyReading.typical` and
     * a ceiling for the same two reasons, restricted to the words both revisions
     * say so that the page having grown or shrunk is not in it, and to the
     * passages neither window is `unknown` about so that a part that stopped
     * reporting is not in it either. One set of passages, so it is the
     * same set on both sides. `change` is the sum of every
     * {@link ComparedPassage.gain}.
     *
     * The words left out are in {@link wordsByMovement} under `unknown`, and a
     * pair with nothing but those gets the `unspoken` silence rather than a
     * change of nought.
     *
     * Each side's own whole-page figure is on `readings.was.typical` and
     * `readings.now.typical`, and those two are **not** comparable: a page that
     * lost four hundred words lowers the second without anybody having read less.
     */
    readonly typical: WordCount | null;
    /**
     * The carried passage the change put most words in front of the average
     * reader, and `null` where none gained any.
     *
     * By {@link ComparedPassage.gain} — words weighted by readers — rather than by
     * the change in `reach`, which is the ranking rule a fall between two siblings
     * already uses: a long passage a tenth of readers newly reach is worth
     * more than a three-word label all of them do.
     */
    readonly mostGained: ComparedPassage | null;
    /** The carried passage it took most words away from, on the same terms. */
    readonly mostLost: ComparedPassage | null;
    /** Why there is no reader comparison, or `null` where there is one. */
    readonly silence: CopyChangeSilence | null;
};

type DeliverOptions = {
    /** Where to post. {@link DEFAULT_READER_SIGNAL_PATH} when absent. */
    readonly url?: string;
    /** The browser's, when absent. A test passes its own. */
    readonly beacon?: SendBeacon | null;
    /** `fetch` with `keepalive`, when absent. */
    readonly post?: PostBatch;
};

type RankedPage = {
    readonly treeId: TreeId;
    readonly revision: number;
    /**
     * The audience this row is about, or `null` where the reading named none.
     *
     * Two forms of one page stand here as two rows, for the reason two revisions
     * of one tree do: both are live, both have readers, and an order that
     * showed one of them would be hiding a page a deployment is serving. Nothing
     * is summed across them — a reader of one form is not a reader of the other,
     * and the two rows' losses are losses from two populations.
     */
    readonly audienceId: AudienceId | null;
    readonly standing: RankStanding;
    /**
     * The window's view floor, carried through from the reading unchanged.
     *
     * A floor and not a count, which is why it is never the denominator of
     * anything here.
     */
    readonly views: number;
    /**
     * Page views counted at the door, exact, or `null` where this revision has no
     * row.
     *
     * The weight behind the row: *three hundred and forty of twelve hundred
     * readers*, where the second number is this and the first is scaled to it.
     */
    readonly opened: number | null;
    /** This page's own straddle rate, which is what scales its loss. */
    readonly inflation: number | null;
    /** The sharpest fall on the page, where it has one. */
    readonly at: ReadingStop | null;
    /** Readers lost at that fall, as the window's counters have it. */
    readonly lost: number | null;
    /**
     * The same loss on the door's scale, which is the key the order is on.
     *
     * Not a count of people and not rounded into one. Withheld where the page has
     * no fall, no reading, or no row to scale it by.
     */
    readonly readers: number | null;
    /**
     * The fall as a share of the readers who reached the part before it, carried
     * through unchanged.
     *
     * Sound without any correction, because both of its counts come off the same
     * rows — so it is published even for a page whose scaled figure is withheld
     * as inconsistent.
     */
    readonly share: number | null;
};

type DeploymentReading = {
    /**
     * Every page with a fall and a scale for it, worst first.
     *
     * Most readers lost at the door's scale, then the larger share, then by tree
     * id and newest revision first — so two pages that lose the same do not
     * reorder on a refresh.
     */
    readonly ranked: readonly RankedPage[];
    /** Every other page, by tree id and newest revision first. */
    readonly unranked: readonly RankedPage[];
    /** The head of the order, which is the page to fix first. */
    readonly worst: RankedPage | null;
    /** How many pages stand in each state, over the ranked and the unranked alike. */
    readonly standings: Readonly<Record<RankStanding, number>>;
    /**
     * Distinct trees across every page read, which is not the number of pages.
     *
     * Two revisions of one tree are two live versions of one page, and both are
     * in the order rather than one replacing the other: a revision shipped an
     * hour ago with four readers on it does not supersede the one that nine
     * thousand read.
     */
    readonly trees: number;
    /**
     * Page views counted at the door across the pages handed in, added.
     *
     * Exact and addable, for the reason no other figure here is: a page view began
     * on one revision of one tree and was counted once. It is a weight rather than
     * a deployment total — this sees the pages its caller read, not the
     * deployment's.
     */
    readonly arrivals: number;
    /**
     * Readings of a revision beyond the first, which were dropped.
     *
     * A caller that concatenated two reads holds one page twice, and a page twice
     * in an order is the one way an order can lie about how much there is to fix.
     */
    readonly duplicated: number;
    /**
     * Door rows for one revision beyond the first, which were ignored.
     *
     * A store keeps one row per revision, so this is a caller's two reads again —
     * and adding them would double a page's arrivals and halve its scaled loss.
     */
    readonly duplicatedRows: number;
};

type PageMovement = {
    /**
     * The pair of siblings it happened at, carried through from the comparison
     * unchanged.
     *
     * Both of its sides are there, so a surface naming the band can also print
     * what each window measured without a second lookup.
     */
    readonly at: ComparedStop;
    /**
     * How much of the page's readers moved, as a share, with the direction in the
     * name rather than in the sign.
     *
     * The magnitude of the comparison's own share movement, which is sound
     * on its own: each side is a fall off its own rows, so each window's straddle
     * divided out before the two met. Published even where the scaled figure is
     * withheld.
     */
    readonly share: number;
    /**
     * The same movement as readers, at the later window's door scale, or `null`
     * where this page has no scale.
     *
     * The key the orders are on. A magnitude and not a count of people: it is a
     * share times a count of views, restated at the scale the door counts in, and
     * it is deliberately not rounded. **Never added across pages or across the
     * two orders** — one reader is in every stop they walked past.
     */
    readonly readers: number | null;
};

type MovedPage = {
    /** The page, which is the earlier reading's tree. */
    readonly treeId: TreeId;
    /** The two revisions compared, which may be the same one read in two windows. */
    readonly revisions: {
        readonly was: number;
        readonly now: number;
    };
    /**
     * The audience the later window was collected under, or `null` where the
     * reading named none.
     *
     * Taken from the later side for the reason only the later window's rows are
     * asked for: the figure being scaled is that window's own. Two forms of one
     * page are two rows here, as they are in every other order this subsystem
     * publishes, and nothing is summed across them — a reader of one form
     * is not a reader of the other.
     */
    readonly audienceId: AudienceId | null;
    readonly standing: MovementStanding;
    /**
     * Each window's view floor, carried through from its own reading unchanged.
     *
     * Floors and not counts, which is why neither is the denominator of anything
     * here. They are what tells a steady page from a window too quiet to have
     * shown a movement.
     */
    readonly views: {
        readonly was: number;
        readonly now: number;
    };
    /**
     * Page views counted at the later door, exact, or `null` where that revision
     * has no row.
     *
     * The weight behind the row: *of the eleven hundred readers this revision
     * had*, where the figures beside it are stated at this number's scale.
     */
    readonly opened: number | null;
    /** The later window's own straddle rate, which is what scales the movements. */
    readonly inflation: number | null;
    /**
     * The comparison's own reason for saying nothing, where it gave one.
     *
     * Carried rather than translated, because a standing says what this order
     * does with the page and the comparison's silence says what the comparison
     * found. A surface printing one sentence prints this one.
     */
    readonly silence: ChangeSilence | null;
    /** The stop the change costs most readers at, where it worsened one. */
    readonly worsened: PageMovement | null;
    /** The stop it keeps most readers at, where it improved one. */
    readonly improved: PageMovement | null;
};

type PageDoor = {
    /**
     * `min(appearances, opened)`: the page views a rollup folded, at the door's
     * scale.
     *
     * It is `appearances ÷ (1 + inflation)` and is **taken as that minimum of two
     * whole numbers**, because the division of three floats agrees with it to
     * fifteen places and not to sixteen — which a share of readers has already
     * been bitten by.
     */
    readonly counted: number;
    /**
     * The row's openings, whatever the silence.
     *
     * Carried even where this page cannot be scaled, because a reading's own
     * count of arrivals is a count of page views the door made and not a count of
     * the ones a share could be taken of.
     */
    readonly opened: number;
    readonly appearances: number;
    readonly drift: number;
    readonly pending: number;
    /** Set where this page cannot be scaled, in the page's own vocabulary. */
    readonly silence: ReachSilence | null;
};

type ReaderReadings = {
    /** Total time on screen. Summed across batches, because `dwelled` is per-batch. */
    readonly dwellMs: Readonly<Record<NodeId, number>>;
    /** Nodes that came into view at all. `viewed` fires once per node per page view. */
    readonly reached: Readonly<Record<NodeId, true>>;
    /**
     * Times the node itself was used — a link followed, a button pressed, a field
     * filled.
     *
     * It is the node the signal names, which is the nearest addressed element to
     * what a reader aimed at. In the starter library that is the control, so a
     * band's count here is zero however busy the band was; `engagements` is the
     * number that is about the band.
     */
    readonly activations: Readonly<Record<NodeId, number>>;
    readonly opens: Readonly<Record<NodeId, number>>;
    readonly closes: Readonly<Record<NodeId, number>>;
    /**
     * Times a form inside the node was submitted and the browser let it go.
     *
     * Filed against the node the signal names, which for the starter library's
     * `loom.form` is the form itself. The band it was the end of is in
     * `engagements`, like every other delegated kind.
     */
    readonly completions: Readonly<Record<NodeId, number>>;
    /**
     * Times a reader used something *inside* the node — pressed, followed, filled,
     * opened or closed, at any depth.
     *
     * The regions' number. Read off the ancestry a delegated signal carries, so a
     * batch whose senders did not walk contributes nothing rather than a guess.
     * Strictly inside, so a control's own use is in `activations` and never here,
     * and a subtree total is the addition.
     *
     * Occurrences rather than readers, because a fold is one page view: *how many
     * of the people reading this used something in the band* is a question about
     * many views, and it is `ReaderTally.engaged`.
     */
    readonly engagements: Readonly<Record<NodeId, number>>;
    /**
     * What each node is, as its signals reported it. Kept because a consumer
     * holding only readings would otherwise have to go back to the tree to render
     * a row, and the signals already say.
     *
     * A region named only as somewhere a press happened inside is in here too, so
     * it gets a row rather than being a number with no name.
     */
    readonly types: Readonly<Record<NodeId, PrimitiveType>>;
    readonly batches: number;
    readonly signals: number;
};

type NodeReading = {
    readonly nodeId: NodeId;
    readonly type: PrimitiveType;
    readonly dwellMs: number;
    readonly reached: boolean;
    readonly activations: number;
    readonly opens: number;
    readonly closes: number;
    /** Times a form inside it was submitted and the browser let it go. */
    readonly completions: number;
    /** Times a reader used something inside it, at any depth. */
    readonly engagements: number;
};

type FormActionSide = {
    readonly treeId: TreeId;
    readonly revision: number;
    /** `null` where the window named none, or named two with neither asked for. */
    readonly audienceId: AudienceId | null;
    /**
     * That side's page-view floor, carried through unchanged.
     *
     * A floor rather than a count, for the reason `parts.ts` gives: distinct view
     * counts cannot be added across rows, so the largest row is the most
     * that can be said from counters alone. Nothing here divides by it — every
     * share in this reading is off one row — and it is carried so a surface can
     * say how big each population was beside what it did.
     */
    readonly views: number;
    /** Element nodes this form has, which two forms of one page need not share. */
    readonly parts: number;
    /** Parts with no element parts under them, whose share is withheld structurally. */
    readonly leaves: number;
    /** Whether this side holds uses and credits them to nobody. */
    readonly unwalked: boolean;
};

type PartActionOfForm = {
    readonly nodeId: NodeId;
    readonly type: PrimitiveType;
    readonly role: PrimitiveRole | null;
    /** The form this part is in. The other form does not have this node at all. */
    readonly audienceId: AudienceId;
    readonly side: PartAction;
};

type ComparedFormAction = {
    readonly nodeId: NodeId;
    /** The type {@link FormActionComparison.one} gives it; `disagreed` names the pair if the other differs. */
    readonly type: PrimitiveType;
    readonly role: PrimitiveRole | null;
    readonly one: PartAction;
    readonly other: PartAction;
    /**
     * The form whose readers acted inside it more often, or `null` where no claim
     * stands.
     *
     * `null` with a {@link ComparedFormAction.gap} of nought is the two forms
     * acting alike; `null` with a `gap` of `null` is nothing being sayable. The
     * two are a long way apart and are deliberately not one value.
     */
    readonly favours: AudienceId | null;
    /**
     * The distance between the two shares, which is never signed.
     *
     * `|one.share − other.share|`, with the direction in
     * {@link ComparedFormAction.favours} rather than in the sign — because a sign
     * is read against an order, and the order here is the alphabet of two
     * audience names and means nothing.
     *
     * `null` where either side withholds its share — a leaf, a part with no row,
     * a part nobody reached — **and on every part of a pair where either side is
     * unwalked**, where the noughts are a filing artefact rather than readers who
     * did nothing.
     */
    readonly gap: number | null;
};

type FormActionsCounted = {
    /** Parts {@link FormActionComparison.one}'s readers acted inside more often. */
    readonly one: number;
    /** Parts {@link FormActionComparison.other}'s readers acted inside more often. */
    readonly other: number;
    /** Parts the two forms acted inside alike. */
    readonly alike: number;
    /** Parts where one side or the other cannot say. */
    readonly unknown: number;
};

type FormActionComparison = {
    /** The side whose audience id sorts lower, or the first argument where no pair of names stands. */
    readonly one: FormActionSide;
    readonly other: FormActionSide;
    /** The two readings this comparison was taken from, so nothing downstream derives them twice. */
    readonly readings: {
        readonly one: PageAction;
        readonly other: PageAction;
    };
    /** Parts both forms have, in the reading order of {@link FormActionComparison.one}. */
    readonly compared: readonly ComparedFormAction[];
    /** Parts exactly one form has, by audience and then by node. */
    readonly onlyIn: readonly PartActionOfForm[];
    /**
     * Shared nodes the two forms give different primitive types.
     *
     * Reported and not dropped, as `FormComparison.disagreed` is: the two shares
     * are each their own form's and stay comparable, while a pair that is a band
     * on one side and a card on the other is a fact about the deltas nobody would
     * otherwise see.
     */
    readonly disagreed: readonly NodeId[];
    /**
     * Shared nodes one form gives an inside and the other does not.
     *
     * The diagnosis this reading needs and its sibling does not. A share is
     * withheld on a leaf for a structural reason, so a part the deltas filled for
     * one audience and left bare for the other has a share on one side and none
     * on the other — and the pair lands in `unknown` with nothing saying why.
     * *The riders' version of this band has nothing in it* is the answer, and it
     * is a fact about the deltas rather than about either readership.
     */
    readonly insideDisagreed: readonly NodeId[];
    readonly counted: FormActionsCounted;
    /**
     * The root, held against itself across the two forms.
     *
     * The one page-level claim either form comparison makes, and it is a division
     * rather than an addition: see the module documentation. `null` where the
     * revision's root is not an element part of both forms.
     */
    readonly whole: ComparedFormAction | null;
    /**
     * The shared part with the widest gap, by node id where two tie.
     *
     * The page itself is never it, because it contains every part it would
     * outrank. `null` where nothing can say.
     */
    readonly sharpest: ComparedFormAction | null;
    readonly silence: FormActionSilence | null;
};

type FormCopySide = {
    readonly treeId: TreeId;
    readonly revision: number;
    /** `null` where the window named none, or named two with neither asked for. */
    readonly audienceId: AudienceId | null;
    /**
     * That side's page-view floor, which is the denominator of every reach below.
     *
     * A floor rather than a count, for the reason `parts.ts` gives: distinct view
     * counts cannot be added across rows, so the largest row is the most
     * that can be said from counters alone.
     */
    readonly views: number;
    /**
     * Every word this form says, counted once.
     *
     * {@link WordsOfForms} accounts for all of them: this side's share of
     * `shared`, of `only` and of `reworded` add to it exactly, which is the
     * property that makes the census a census rather than three lists.
     */
    readonly words: number;
    /** Passages this form has that say something, which two forms need not share. */
    readonly passages: number;
    /** Words this form says in parts its own window can speak for. */
    readonly spoken: number;
};

type PassageOfForm = {
    readonly nodeId: NodeId;
    readonly type: PrimitiveType;
    readonly role: PrimitiveRole | null;
    /** The form this passage is in. The other form does not have this node at all. */
    readonly audienceId: AudienceId;
    /** The passage itself, as that form's own window read it. */
    readonly passage: Passage;
    /** What that form's window said about reaching it. */
    readonly side: PassageSide;
};

type ComparedFormPassage = {
    readonly nodeId: NodeId;
    /** The type {@link FormCopyComparison.one} gives it; `disagreed` names the pair if the other differs. */
    readonly type: PrimitiveType;
    readonly role: PrimitiveRole | null;
    /** The words, the same number on both sides because they are the same words. */
    readonly words: number;
    /** The text itself, so a passage can be quoted back without a second join. */
    readonly text: readonly string[];
    /**
     * Whether either form's part declares no `copy`, so {@link words} is a floor.
     *
     * The visible words are the same on both sides; what a floor withholds is
     * whether there are more. A form may be floored where the other is not, when
     * a prop no type declares holds something for one audience and nothing for
     * the other — so this is either side, and the figures it qualifies are
     * qualified for both.
     */
    readonly floored: boolean;
    readonly one: PassageSide;
    readonly other: PassageSide;
    /**
     * The form whose readers reached this passage more often, or `null` where no
     * claim stands.
     *
     * **Read off the two reaches rather than off {@link gap}**, which is the
     * module documentation's one departure from the two sibling comparisons: a
     * reach is exact where a word count is a floor, so the direction
     * survives an undeclared `copy` prop and the magnitude does not.
     *
     * `null` with a `gap` of nought is the two forms reaching it alike; `null`
     * with a `gap` of `null` is nothing being sayable. The two are a long way
     * apart and are deliberately not one value.
     */
    readonly favours: AudienceId | null;
    /**
     * The words this passage puts in front of one form's average reader over and
     * above the other's: `words × |one.reach − other.reach|`.
     *
     * Never signed — the direction is in {@link favours}, because a sign is read
     * against an order and the order here is the alphabet of two audience names
     * and means nothing.
     *
     * `null` where either side held no views **or** either side's standing is
     * `unknown`: a reach of nought that is a missing counter is not a
     * reader who did not arrive, and subtracting against it would publish the
     * other form's whole reach as a difference between two populations.
     *
     * A floor on {@link words} scales it toward nought and cannot change the form
     * it is about, so it is published where the page figures are withheld.
     */
    readonly gap: number | null;
};

type RewordedFormPassage = {
    readonly nodeId: NodeId;
    /** The type {@link FormCopyComparison.one} gives it. */
    readonly type: PrimitiveType;
    readonly role: PrimitiveRole | null;
    /** The two word counts, which is why there is no single one. */
    readonly words: {
        readonly one: number;
        readonly other: number;
    };
    /** Whether either form declares no `copy`, so its word count is a floor. */
    readonly floored: boolean;
    readonly one: PassageSide;
    readonly other: PassageSide;
    /**
     * The form that says more words here, or `null` where the two say as many
     * words differently.
     *
     * The sentence this whole reading was asked for — *the pro form says four
     * hundred words in this band and the free form says ninety* — published
     * rather than left to a surface to subtract, so that two screens cannot
     * disagree about which way round it is. It is a fact about the deltas and
     * about no reader, and under a floor it is the one claim here that can be
     * wrong: an undeclared `copy` prop understates one side only.
     */
    readonly wordier: AudienceId | null;
};

type WordsOfForms = {
    /** Words both forms say, word for word, in a node both forms have. */
    readonly shared: number;
    /** Words of passages exactly one form has, by form. */
    readonly only: {
        readonly one: number;
        readonly other: number;
    };
    /**
     * Those words, by what each form's own window said about reaching them. Each
     * form's three add to its own {@link only}.
     *
     * *Of the three hundred words the pro form says and the free form never sees,
     * forty have been reached.* It is the one figure here about words the other
     * form's readers could not have read, so it has no comparison and needs none.
     */
    readonly onlyByStanding: {
        readonly one: Readonly<Record<PartStanding, number>>;
        readonly other: Readonly<Record<PartStanding, number>>;
    };
    /** Words of passages both forms have and neither says the same way, by form. */
    readonly reworded: {
        readonly one: number;
        readonly other: number;
    };
};

type FormCopyCounted = {
    /** Passages {@link FormCopyComparison.one}'s readers reached more often. */
    readonly one: number;
    /** Passages {@link FormCopyComparison.other}'s readers reached more often. */
    readonly other: number;
    /** Passages the two forms reached alike. */
    readonly alike: number;
    /** Passages where one form or the other cannot say. */
    readonly unknown: number;
};

type SharedWordsRead = {
    /** `Σ(readers × words) ÷ views` for {@link FormCopyComparison.one}. */
    readonly one: number;
    /** The same for {@link FormCopyComparison.other}. */
    readonly other: number;
    /**
     * `|one − other|`, with the direction in {@link favours}.
     *
     * **Not the sum of the rows' gaps**, and the difference is the module
     * documentation's: a row's gap is unsigned, so two passages favouring opposite
     * forms add there and cancel here.
     */
    readonly gap: number;
    /** The form whose average reader got to more of the shared words. */
    readonly favours: AudienceId | null;
};

type FormCopyComparison = {
    /** The side whose audience id sorts lower, or the first argument where no pair of names stands. */
    readonly one: FormCopySide;
    readonly other: FormCopySide;
    /** The two copy readings this comparison was taken from, so nothing downstream derives them twice. */
    readonly readings: {
        readonly one: CopyReading;
        readonly other: CopyReading;
    };
    /** The census of what each form says, with no reader in it. */
    readonly says: WordsOfForms;
    /** Passages both forms say the same way, in the reading order of {@link one}. */
    readonly compared: readonly ComparedFormPassage[];
    /** Passages both forms have and neither says the same way, in the same order. */
    readonly reworded: readonly RewordedFormPassage[];
    /** Passages exactly one form has, by audience and then by node. */
    readonly onlyIn: readonly PassageOfForm[];
    /**
     * Shared nodes the two forms give different primitive types.
     *
     * Reported and not dropped, as both sibling comparisons report it: the two
     * reaches are each their own form's and stay comparable, while a node that is
     * a band on one side and a card on the other is a fact about the deltas
     * nobody would otherwise see.
     */
    readonly disagreed: readonly NodeId[];
    /** Shared passages by which form's readers reached them more often. */
    readonly counted: FormCopyCounted;
    /**
     * The words those passages say, falling the same way. The four add to
     * {@link WordsOfForms.shared}.
     *
     * Published beside {@link counted} because the two survive different things:
     * a count of passages is right under a floor — a part that declares no `copy`
     * is one part whatever it is hiding — and a count of words is not. A surface
     * that has to be right about mass reads this row and a surface that has to be
     * right under a floor reads the other.
     */
    readonly wordsCounted: FormCopyCounted;
    /** Shared passages whose words are a floor. */
    readonly floored: number;
    /**
     * The shared passages neither form's readers reached, most words first and
     * then in reading order.
     *
     * The words the deltas have not managed to put in front of anybody, which is
     * the list a person can act on without reading anything else. Ranked by words
     * for the reason one window's reading ranks them: the passage nobody
     * saw that costs the page most is the long one, not the first one.
     *
     * `skipped` on **both** sides only. A passage `unknown` on either side is in
     * {@link wordsCounted} where it can be seen and not acted on, because putting
     * it here would turn *nothing can be said* into *nobody read this*.
     */
    readonly unseenByEither: readonly ComparedFormPassage[];
    /** The shared words each form's average reader got to; `null` where {@link silence} says why not. */
    readonly typical: SharedWordsRead | null;
    /**
     * The shared passage the two forms read most differently, by node id where
     * two tie.
     *
     * By {@link ComparedFormPassage.gap} — words weighted by readers — rather than
     * by the difference in reach, which is the ranking rule a fall between two
     * siblings already uses. There is no page row to exclude here, which
     * both siblings have: a passage's words are its own and never its subtree's,
     * so the root's passage is one row among the others and contains none of them.
     */
    readonly sharpest: ComparedFormPassage | null;
    readonly silence: FormCopySilence | null;
};

type FormSide = {
    readonly treeId: TreeId;
    readonly revision: number;
    /** `null` where the window named none, or named two with neither asked for. */
    readonly audienceId: AudienceId | null;
    /**
     * That side's page-view floor, which is the denominator of every reach below.
     *
     * A floor rather than a count, for the reason `parts.ts` gives: distinct view
     * counts cannot be added across rows, so the largest row is the most
     * that can be said from counters alone.
     */
    readonly views: number;
    /** Element nodes this form has, which two forms of one page need not share. */
    readonly parts: number;
};

type FormPartSide = {
    readonly standing: PartStanding;
    /** Distinct page views of this form that reported the part coming into view. */
    readonly readers: number;
    /** That side's own view floor, carried so the share below can be checked. */
    readonly views: number;
    /**
     * {@link FormPartSide.readers} over {@link FormPartSide.views}, or `null`
     * where that window held none.
     *
     * A ceiling on the share of that form's readers who reached the part:
     * `reached` leans up by the views that straddled a rollup window and
     * `views` leans down by being a floor, and the same lean is in both terms of
     * each side. Above 1 is not clamped — a figure cut to fit its own ceiling is a
     * fault made undrawable rather than visible.
     */
    readonly reach: number | null;
};

type PartOfForm = {
    readonly nodeId: NodeId;
    readonly type: PrimitiveType;
    readonly role: PrimitiveRole | null;
    /** The form this part is in. The other form does not have this node at all. */
    readonly audienceId: AudienceId;
    readonly side: FormPartSide;
};

type ComparedForm = {
    readonly nodeId: NodeId;
    /** The type {@link FormComparison.one} gives it; `disagreed` names the pair if the other differs. */
    readonly type: PrimitiveType;
    readonly role: PrimitiveRole | null;
    readonly one: FormPartSide;
    readonly other: FormPartSide;
    /**
     * The form whose readers reached it more often, or `null` where no claim
     * stands.
     *
     * `null` with a {@link ComparedForm.gap} of nought is the two forms reaching
     * it alike; `null` with a `gap` of `null` is nothing being sayable. The two
     * are a long way apart and are deliberately not one value.
     */
    readonly favours: AudienceId | null;
    /**
     * The distance between the two reaches, which is never signed.
     *
     * `|one.reach − other.reach|`, with the direction in
     * {@link ComparedForm.favours} rather than in the sign — because a sign is
     * read against an order, and the order here is the alphabet of two audience
     * names and means nothing.
     *
     * `null` where either side held no views **or** either side's standing is
     * `unknown`: a reach of nought that is a missing counter is not a
     * reader who did not arrive, and subtracting against it would publish the
     * other side's whole reach as a difference between two populations.
     */
    readonly gap: number | null;
};

type FormsCounted = {
    /** Parts {@link FormComparison.one}'s readers reached more often. */
    readonly one: number;
    /** Parts {@link FormComparison.other}'s readers reached more often. */
    readonly other: number;
    /** Parts the two forms reached alike. */
    readonly alike: number;
    /** Parts where one side or the other cannot say. */
    readonly unknown: number;
};

type FormComparison = {
    /** The side whose audience id sorts lower, or the first argument where no pair of names stands. */
    readonly one: FormSide;
    readonly other: FormSide;
    /** Parts both forms have, in the reading order of {@link FormComparison.one}. */
    readonly compared: readonly ComparedForm[];
    /** Parts exactly one form has, by audience and then by node. */
    readonly onlyIn: readonly PartOfForm[];
    /**
     * Shared nodes the two forms give different primitive types.
     *
     * Reported and not dropped, the way `LibraryReading.roleDisagreed` is: the
     * two reaches are each their own form's and stay comparable, while a pair that
     * is a band on one side and a card on the other is a fact about the deltas
     * nobody would otherwise see.
     */
    readonly disagreed: readonly NodeId[];
    readonly counted: FormsCounted;
    /** The shared part with the widest gap, by node id where two tie; `null` where none can say. */
    readonly sharpest: ComparedForm | null;
    readonly silence: FormComparisonSilence | null;
};

type FunnelStage = 
/** Arrivals that never satisfied the pair's first end. */
"before"
/** Arrivals that satisfied the first end and not the second. */
 | "between";

type PairEnds = {
    readonly from: EndStanding;
    readonly to: EndStanding;
};

type FunnelReach = {
    readonly treeId: TreeId;
    readonly revision: number;
    /**
     * The audience whose answers this reading is of, or `null` where the reading
     * it was taken from named none.
     *
     * Carried rather than consumed and dropped. The rows are already scoped to it
     * below, so this adds nothing to what is read — what it adds is the ability
     * of a comparison to refuse a pair of two populations, which it cannot do
     * from two readings that have forgotten which population each was of.
     */
    readonly audienceId: AudienceId | null;
    /**
     * Every population the window named, deduplicated and in a stable order.
     *
     * The reading's own census and the funnel rows' together, because either
     * alone can be the ambiguous one: a caller may hand in a page reading of one
     * form and funnel rows of two, or the reverse. `[]` is a window that never
     * carried the column, which is *nothing here says* and not *one
     * audience*.
     *
     * Two members with {@link FunnelReach.audienceId} `null` is the state in
     * which no pair is read at all — see the module note on what a window of two
     * forms is refused for.
     */
    readonly audiences: readonly AudienceId[];
    /** Page views that began on this revision. Exact, and addable. */
    readonly opened: number;
    /** The same page views as the rollups counted them: once per window each appeared in. */
    readonly appearances: number;
    /** Appearances in excess of openings — the straddle, measured. Never negative. */
    readonly drift: number;
    /** Openings whose reading no rollup has folded yet. The other sign of the same subtraction. */
    readonly pending: number;
    /** `drift ÷ opened`: how generous every distinct count here is. `null` when nothing opened. */
    readonly inflation: number | null;
    /** When the page-view row last moved, or `null` where there is no row. */
    readonly updatedAt: string | null;
    /** Set where no share can be given, and the reason. `null` where they can. */
    readonly silence: ReachSilence | null;
    /**
     * Nobody's visit spanned two windows, so there is nothing to divide out: the
     * rates are exact and each `rateAtMost` equals its `rate`.
     *
     * False under a silence, and false while any opening is pending.
     */
    readonly exact: boolean;
    /**
     * The revision's pairs, ordered by their two ends so a screen does not
     * reorder on a refresh. Deliberately not ranked — see the module note.
     */
    readonly pairs: readonly PairReach[];
    /** Page-view rows for another tree or revision, and ignored. */
    readonly foreign: number;
    /** Page-view rows for this revision beyond the first, where the first stands. */
    readonly duplicated: number;
    /**
     * Funnel rows for another tree or revision, and ignored.
     *
     * Filtered rather than trusted for the same reason the page-view rows are:
     * answering one revision's question with another revision's counters is a
     * figure nothing downstream could catch.
     */
    readonly foreignPairs: number;
    /**
     * Funnel rows for this revision in another audience, and ignored.
     *
     * The same question, answered for the other form of the page. Not foreign —
     * it is this page's — and not a duplicate: two populations answering one
     * question is two answers, and the one this reading wants is its own.
     */
    readonly otherAudiencePairs: number;
    /**
     * Funnel rows naming a pair already seen, where every one after the first was
     * ignored.
     *
     * A store keeps one row per pair per revision per audience, so a second row
     * for one pair **within one population** is a caller who concatenated two
     * reads, and adding them would double a total that is already one.
     *
     * It says *within one population* rather than asserting the audience was
     * picked first, which is what it used to say and what made the fault below
     * invisible: where the asking named no audience, two forms' answers to one
     * question were two rows sharing this key, and the second was counted here —
     * a real second population reported as the one number in this reading nobody
     * reads as an undercount. A window of two forms is now read as neither, so
     * this counts only what it always claimed to.
     */
    readonly duplicatedPairs: number;
    /**
     * Pairs with an end this revision does not have, counted off
     * {@link FunnelReach.pairs} and therefore once each.
     *
     * The figure a screen leads with when it is not nought: *three of your five
     * funnel questions are about parts this version of the page no longer has.*
     */
    readonly stalePairs: number;
    /** Of those, the ones with a count against the missing end. Counted off the same list. */
    readonly orphanedPairs: number;
};

type QuestionMovement = 
/** Both ends are in both revisions, so the two sides answer the same question. */
"asked"
/**
 * The earlier revision had both ends and the later one is missing one.
 *
 * **The row to lead with when it is not nought.** The counters cannot move
 * again and every figure on the later side is withheld, so a funnel that
 * looks abandoned is a question to re-point rather than readers who stopped
 * buying. The change broke it, and nothing about readers is wrong.
 */
 | "broken"
/** The earlier revision was missing an end and the later one has both: the change put it back. */
 | "restored"
/** An end is missing from both revisions, so neither side was ever answering. */
 | "stale";

type ComparedFunnel = {
    /** The pair as the later window holds it, which is the same question either way. */
    readonly pair: FunnelPair;
    /** The whole of what the earlier window said about it. */
    readonly was: PairReach;
    /** The whole of what the later window said about it. */
    readonly now: PairReach;
    readonly movement: FunnelMovement;
    /** What the change did to whether the question names anything. */
    readonly question: QuestionMovement;
    /**
     * `now.rate ÷ was.rate` — of the readers who got to the first end, how much
     * likelier they are to finish.
     *
     * Each side is two counts off one row, so each window's straddle has very
     * nearly divided out before the two meet. **It is still a ratio
     * of two figures that lean down** by an amount the deployment's rollup window
     * sets, which is what the bracket is for.
     *
     * `unmeasured` where either side has no rate, and `from-nothing` where the
     * earlier one is nought: *nobody finished and now somebody does* is
     * {@link movement}'s answer as well, and a quotient is a figure a surface
     * divides and ranks by.
     */
    readonly rateRatio: Ratio;
    /**
     * The least the true ratio could be: `now.rate ÷ was.rateAtMost`.
     *
     * `null` wherever {@link rateRatio} holds no quotient, and wherever either
     * side's ceiling is withheld — the ceiling is built from the door's drift, so
     * it goes when the door does.
     *
     * **A bound and not a figure of its own**, which is why it is a bare `null`
     * where the ratio it brackets names its absence: a bracket around a
     * quotient that does not exist has nothing to say that the quotient has not
     * said already, and a bracket missing where the quotient is there is the
     * door's drift and nothing else.
     */
    readonly rateRatioAtLeast: number | null;
    /** The most the true ratio could be: `now.rateAtMost ÷ was.rate`. `null` on the same terms. */
    readonly rateRatioAtMost: number | null;
    /**
     * The bracket clears 1, so the rate moved by more than the straddle alone
     * could account for.
     *
     * `false` is the figure to draw rather than suppress: *the rate fell by a
     * third and the rollup window can explain all of it* is a sentence about the
     * deployment's configuration, and it is the one a card showing a bare ratio
     * prints as a collapse. `null` where there is no bracket.
     */
    readonly rateMoved: boolean | null;
    /**
     * `now.entry.share ÷ was.entry.share` — how much likelier an arrival is to
     * get to the first end.
     *
     * `unmeasured` under any silence and where either side withheld the share,
     * `from-nothing` where the earlier one is nought.
     */
    readonly entryRatio: Ratio;
    /**
     * `now.conversion.share ÷ was.conversion.share` — how much likelier an
     * arrival is to finish, which is the figure a deployment means by *did the
     * change work*.
     *
     * Absent on the same terms as {@link entryRatio}.
     */
    readonly conversionRatio: Ratio;
    /**
     * The later window's reach at the earlier window's closing rate, as a share
     * of arrivals: the conversion share if only getting there had moved.
     */
    readonly ifOnlyEntryMoved: number | null;
    /** The other diagonal: the conversion share if only the closing had moved. */
    readonly ifOnlyClosingMoved: number | null;
    /** Which side was enough on its own. `null` where the conversion share did not move. */
    readonly cause: ConversionCause | null;
    /**
     * The movement in the conversion share, put on the later window's scale:
     * `(now.conversion.share − was.conversion.share) × now.opened`.
     *
     * **A mass for ranking and not a count of people**, as every `…Moved` figure
     * in this subsystem is. A difference of two windows' conversion counts
     * is refused here and nowhere published: both are generous by their own
     * window's straddle, and the inflation does not divide out of a difference
     * whose two terms are in different windows.
     *
     * `null` under any silence and wherever either share is withheld.
     */
    readonly readersMoved: number | null;
};

type FunnelChange = {
    /** The earlier reading's tree. The two agree unless `silence` is `different-trees`. */
    readonly treeId: TreeId;
    readonly revisions: {
        readonly was: number;
        readonly now: number;
    };
    /**
     * The audience each side was of, where its reading named one.
     *
     * As `ReadingChange.audiences` carries it, and for the same reason: a `null`
     * on either side is why an unprovable pair of populations is compared rather
     * than refused.
     */
    readonly audiences: ComparedAudiences;
    /** The two funnel readings this comparison is made of. */
    readonly readings: {
        readonly was: FunnelReach;
        readonly now: FunnelReach;
    };
    /**
     * Every question both windows were asked, ordered by the pair's two ends so a
     * screen does not reorder on a refresh.
     *
     * Deliberately not ranked, as the readings it is made of are not: two pairs
     * are two questions about different nodes, and the pair that moved the most
     * readers is reliably whichever first end is shallowest in the page.
     * {@link mostGained} and {@link mostLost} are the two a surface leads with.
     */
    readonly compared: readonly ComparedFunnel[];
    /**
     * Questions only the later window was asked, as it answered them.
     *
     * A deployment that added a pair, and the window before it was added has
     * nothing to say — which is a fact about the configuration rather than about
     * the change, and the reason this is a list and not a movement.
     */
    readonly added: readonly PairReach[];
    /** Questions only the earlier window was asked, as it answered them. */
    readonly removed: readonly PairReach[];
    /** Compared pairs by what happened to the verdict. The five add to {@link compared}'s length. */
    readonly movements: Readonly<Record<FunnelMovement, number>>;
    /** Compared pairs by what the change did to the question. The four add to {@link compared}'s length. */
    readonly questions: Readonly<Record<QuestionMovement, number>>;
    /**
     * The compared pair whose conversion share gained the most readers at the
     * later window's scale, or `null` where none gained.
     *
     * Ranked by {@link ComparedFunnel.readersMoved} — by headcount rather than by
     * share, which is the rule a fall between two siblings is ranked by: a
     * funnel two readers in three now finish is a better rate and a smaller win
     * than one four hundred in a thousand do.
     */
    readonly mostGained: ComparedFunnel | null;
    /** The compared pair that lost the most, by the same rule. `null` where none lost. */
    readonly mostLost: ComparedFunnel | null;
    /**
     * Compared pairs whose rate ratio is given and whose bracket contains 1, so
     * the straddle alone could account for the whole movement.
     *
     * The figure that says how much of this screen to believe: a reading where
     * most of the pairs are in here is a reading of the deployment's rollup
     * window.
     */
    readonly undecided: number;
    /**
     * Neither window had a page view that spanned a rollup boundary, so every
     * rate on both sides is exact and every bracket is a point.
     *
     * False wherever either window's drift is unknown, which is every state of
     * the door: there is nothing to measure the straddle with.
     */
    readonly exact: boolean;
    /**
     * Pairs naming a question already seen on that side, where every one after
     * the first was ignored.
     *
     * A reading built by `funnelReachOf` holds one row per question, so this is a
     * caller that concatenated two readings. Counting the second occurrence would
     * put one window's funnel in a comparison twice, which is the error that is
     * permanent once the counters hold it and the one this subsystem
     * checks for by habit.
     */
    readonly duplicated: number;
    /** Set where a figure is missing and why. `null` where nothing is. */
    readonly silence: FunnelChangeSilence | null;
};

type FaultRemedy = 
/** The pages: a newer broadcaster, or one whose delegation walks the ancestry. */
"senders"
/** The deployment's own configuration: the rollup window. */
 | "configuration"
/** The surface that asked: it handed in a tree and a window that do not match, or two reads. */
 | "caller"
/**
 * Nothing the rows can name.
 *
 * One fault out of seven, and it is the honest answer rather than a gap: a
 * missing door row is an old sender, an expired row or a hand-built counter,
 * and inventing one of the three is worse than naming none.
 */
 | "undetermined";

type PageHealth = {
    readonly treeId: TreeId;
    readonly revision: number;
    /**
     * The audience this row is about, or `null` where the reading named none.
     *
     * Two forms of one page are two rows here and not one page counted twice
     * (`readingKeyOf`), for the reason two revisions of one tree are two rows: a
     * deployment serving both is running both, and a health screen that showed
     * one of them would be hiding a live form of a live page.
     */
    readonly audienceId: AudienceId | null;
    readonly standing: HealthStanding;
    /**
     * Every fault, in the order {@link COLLECTION_FAULTS} publishes them, which is
     * the order they are worth reading in: the one that costs the denominator
     * first, the three that are the deployment's, then the caller's.
     *
     * Empty on every standing but `faulted`.
     */
    readonly faults: readonly CollectionFault[];
    /**
     * The window's view floor, carried through from the reading unchanged.
     *
     * A floor and not a count, which is why it is never ranked and never
     * added to an arrival count here.
     */
    readonly views: number;
    /**
     * Page views counted at the door, exact, or `null` where this revision has no
     * row.
     *
     * On a faulted page these are the readers whose measurement its faults
     * affect, which is what makes one faulted page worse than another.
     */
    readonly arrivals: number | null;
    /** The same page views as the rollups saw them, or `null` with no row. */
    readonly appearances: number | null;
    /** This revision's own straddle rate, or `null` where nothing has opened. */
    readonly inflation: number | null;
    /**
     * Openings no rollup has folded yet, which is a figure and never a fault here.
     *
     * Zero where there is no door row, because an absent row reports no openings
     * rather than none pending.
     */
    readonly pending: number;
    /**
     * When a rollup last folded a window holding page views of this revision, or
     * `null` where nothing attests one — including every revision with no door
     * row at all.
     *
     * Published whether or not a schedule was handed in, because *the last fold
     * of this page was at nine this morning* is the sentence an operator reads
     * before any verdict about it. `null` is not *never folded*: a row
     * written before the column existed says the same thing, and the first fold
     * after an upgrade fills it in.
     */
    readonly foldedAt: string | null;
    /** Counters naming nodes this revision does not contain. */
    readonly orphaned: number;
    /** Node counters and door rows handed in more than once, added. */
    readonly doubled: number;
};

type IngestOutcome = {
    readonly batches: number;
    readonly signals: number;
    /**
     * Page views this delivery opened, which is what the exact counter moved by.
     *
     * Zero unless the caller keeps that counter and the delivery actually opened
     * something — most deliveries of a page view are the middle of one.
     */
    readonly opened: number;
    /**
     * Page views counted against a region, which is zero unless the caller said
     * where the delivery came from and the delivery opened a page view.
     */
    readonly regions: number;
    /**
     * Why a counter did not move, when a store refused it.
     *
     * Present and the delivery still stands: the batch is already kept, and a
     * sender told to retry would deliver it twice, which is the one failure in
     * this subsystem that cannot be undone. So a lost count is a counter
     * that did not move, reported here rather than raised — the same trade a sink
     * makes when a browser refuses a beacon.
     */
    readonly openingError?: ReaderSignalStoreError;
    readonly regionError?: ReaderSignalStoreError;
};

type RegionCounter = {
    readonly store: ReaderRegionStore;
    readonly region: ReaderRegion;
};

type DoorCounters = {
    /** When, as an instant every counter this delivery moves is stamped with. The caller's clock. */
    readonly at: string;
    /** Where the delivery came from. Absent on a deployment that does not count regions. */
    readonly region?: RegionCounter;
    /**
     * How many page views began. No switch guards it where it is wired, because a
     * count of page views of a revision names nowhere and nobody — it is the
     * denominator everything else is a rate against.
     */
    readonly openings?: ReaderOpeningCounter;
};

type IngestError = {
    readonly code: "invalid-delivery";
    /** Which batch of the delivery, so a sender with one bad batch can be told which. */
    readonly index: number;
    readonly issues: ReaderSignalParseError["issues"];
} | {
    readonly code: "too-many";
    readonly limit: number;
    readonly given: number;
} | ReaderSignalStoreError;

type IntakePolicy = {
    /** The largest delivery the door will read, in bytes. */
    readonly maxBytes: number;
    /** Deliveries one subject may make inside a window. */
    readonly deliveries: number;
    readonly windowMs: number;
    /** How many subjects the counter distinguishes before {@link CROWDED_SUBJECT}. */
    readonly subjects: number;
};

type IntakeCount = {
    readonly deliveries: number;
    readonly windowStartedAt: number;
};

type IntakeVerdict = {
    readonly code: "admitted";
    readonly count: IntakeCount;
} | {
    readonly code: "too-large";
    readonly count: IntakeCount;
    readonly limit: number;
    readonly given: number;
} | {
    readonly code: "too-often";
    readonly limit: number;
    readonly retryAfterMs: number;
};

type IntakeGate = {
    /**
     * The policy this gate counts by.
     *
     * Carried on the gate rather than left beside it, because a caller holding
     * both had two copies that could disagree — and the one that decides is
     * whichever the gate was built with, silently. A door has one policy.
     */
    readonly policy: IntakePolicy;
    readonly admit: (subject: string, bytes: number, now: number) => IntakeVerdict;
    /** How many subjects are being counted. For a status endpoint, not for a decision. */
    readonly subjects: () => number;
};

type ReaderSignalStoreError = {
    readonly code: "unavailable";
    readonly detail: string;
};

type ReceivedBatch = ReaderSignalBatch & {
    readonly seq: number;
    readonly receivedAt: string;
    /**
     * The audience it was **filed** under, which is resolved rather than
     * optional.
     *
     * `audience` is what the sender said and may be absent; this is what the
     * buffer stored, and a stored row always names one — `aud_everyone` where the
     * sender named nothing. A fold reads this, so that a window holding two
     * audiences folds into two sets of counters rather than one.
     */
    readonly audienceId: AudienceId;
};

type ReaderSignalReadRequest = {
    /** Absent reads every tree the handle can see, which is the scope rule. */
    readonly treeId?: TreeId;
    /** A cursor from a previous page's `older`/`newer`, passed back unread. */
    readonly cursor?: string;
    /** Default `newer`, which with no cursor is the oldest page — where rollup starts. */
    readonly direction?: PageDirection;
    readonly limit?: number;
};

type ReaderSignalPage = PageEnds & {
    /** Always ascending by `seq`, whichever end the page was taken from. */
    readonly batches: readonly ReceivedBatch[];
};

interface ReaderSignalJournal {
    readonly receive: (batches: readonly ReaderSignalBatch[]) => Promise<Result<void, ReaderSignalStoreError>>;
    readonly read: (request?: ReaderSignalReadRequest) => Promise<Result<ReaderSignalPage, ReaderSignalStoreError>>;
    readonly forget: (request: ForgetBefore) => Promise<Result<ForgetOutcome, ReaderSignalStoreError>>;
}

type KindKey = {
    readonly by: "type";
    readonly type: PrimitiveType;
}
/** `null` is the row for parts whose type declared no role, which is most of a library today. */
 | {
    readonly by: "role";
    readonly role: PrimitiveRole | null;
};

type KindReading = {
    readonly kind: KindKey;
    /** What part a type plays, or `null`. Always `null` on a role row, which carries it as its key. */
    readonly role: PrimitiveRole | null;
    /** Element nodes of this kind across the readings. */
    readonly placements: number;
    /** Distinct trees it stands in, which is not the number of placements and not the number of readings. */
    readonly trees: number;
    /** Distinct revisions it stands in: two live revisions of one page are two. */
    readonly revisions: number;
    /** Placements by standing. The three add to {@link placements}. */
    readonly standings: Readonly<Record<PartStanding, number>>;
    /**
     * The share of its placements at least one reader reached. `null` where
     * {@link silence} says why not.
     *
     * *At least one*, which is what a standing of `read` means and not what a
     * person reads the word as. `read ÷ (read + skipped)`, so a placement
     * nothing can be said about is in neither term rather than counted as a skip.
     *
     * **Places and not people.** See the module documentation: it is sound as a
     * statement about where this kind of part stands and is not a share of
     * readers.
     */
    readonly readShare: number | null;
    /**
     * Why {@link readShare} is not there, and `null` where it is.
     *
     * About the read share and not about the row: {@link wordShare} is absent for
     * a reason of its own and says so where it is, which is how a copy reading
     * already publishes a share beside a withheld figure.
     */
    readonly silence: KindSilence | null;
    /**
     * Every word this kind says across its placements, counted once.
     *
     * Addable for the reason no view count here is: a part's words are its own and
     * the words of a page are partitioned across its parts exactly once, so
     * two placements' words are two different sentences.
     */
    readonly words: number;
    /** Words said by a placement at least one reader reached. */
    readonly wordsReached: number;
    /**
     * {@link wordsReached} over {@link words}; `null` where this kind says nothing
     * at all, which a spacer, a rule and a stack that only holds other parts all
     * do.
     */
    readonly wordShare: number | null;
    /**
     * Placements whose words are a floor, because the type declares no `copy`
     *.
     *
     * The direction {@link wordShare} is wrong in, handed over rather than
     * summarised: a floored placement understates the numerator and the
     * denominator together where it was reached, and the denominator alone where
     * it was skipped. On a library built from the starter primitives this is
     * nought; on one built from a deployment's own it is most of the rows,
     * and that is the thinness the server-side join already names rather than a
     * fault here.
     */
    readonly floored: number;
    /**
     * Time on screen across its placements, added.
     *
     * A volume of attention and **not a duration anybody spent**: a part is on
     * screen while its children are, so a nested placement's seconds are its
     * ancestors' too. Comparable between two kinds of the same depth and
     * meaningless added across kinds, which is why nothing here adds it.
     */
    readonly dwellMs: number;
    /** Presses, filed against the part the reader used, so no press is in two rows. */
    readonly activations: number;
    readonly opens: number;
    readonly closes: number;
    /** Forms this kind of part let go. */
    readonly completions: number;
};

type LibraryReading = {
    /**
     * Every type that stands anywhere, most placements skipped first.
     *
     * Then the lower read share, then by type, so two kinds that are skipped
     * equally often do not reorder on a refresh.
     */
    readonly byType: readonly KindReading[];
    /**
     * Every role in the vocabulary that stands anywhere, then the row for parts
     * whose type declared none, in the same order as {@link byType}.
     *
     * Thin today for the reason every role figure in this subsystem is thin:
     * nothing in `src/primitives/` declares one, so nearly every part is in the
     * `null` row. The join is at read time, so the day a role is declared
     * every counter already stored reinterprets and these rows start answering
     * without a migration.
     */
    readonly byRole: readonly KindReading[];
    /** Readings counted, which is revisions of pages and not trees. */
    readonly pages: number;
    /** Distinct trees across them. */
    readonly trees: number;
    /** Element nodes across them, which is the sum of every type row's placements. */
    readonly placements: number;
    /** Placements by standing, over the whole library. */
    readonly standings: Readonly<Record<PartStanding, number>>;
    /**
     * The type skipped in the most places, which is the kind to look at first.
     *
     * By the **count** of places and not by the share, for the reason a page's
     * falls are ranked by the readers they lose: a kind skipped in its one
     * and only place is a perfect share and a smaller problem than one skipped in
     * seven of nine. `null` where nothing anywhere was skipped — a healthy
     * deployment and an unmeasured one both, which {@link standings} tells apart.
     *
     * A type and never a role, because a type is the thing an author can replace.
     */
    readonly mostSkipped: KindReading | null;
    /** The type used most, by presses. A count of things that happened, not of readers. */
    readonly mostUsed: KindReading | null;
    /**
     * Readings of a revision beyond the first, which were dropped.
     *
     * A caller that concatenated two reads holds one page twice, and a page twice
     * in a census is the one way a census can lie about how much of a library
     * there is.
     */
    readonly duplicated: number;
    /**
     * Types whose readings disagreed about the role they play, where the first
     * reading's answer stands.
     *
     * The one failure this join can have that nothing else would catch: readings
     * joined against two different registries, concatenated. A type plays one part
     *, so a disagreement is not a fact about the library — it is two
     * libraries read as one, and every role row below is then about neither.
     */
    readonly roleDisagreed: readonly PrimitiveType[];
};

type KindAction = {
    readonly kind: KindKey;
    /** What part a type plays, or `null`. Always `null` on a role row, which carries it as its key. */
    readonly role: PrimitiveRole | null;
    /** Element nodes of this kind across the readings, as the census counts them. */
    readonly placements: number;
    /**
     * Placements that bear element parts, which are the ones the question exists
     * for.
     *
     * Taken off the tree the reading was built from, so it is a property of the
     * pages and not of the window: a part keeps its children in a window nobody
     * read.
     */
    readonly insides: number;
    /**
     * Placements with no element part under them, which are in no term here.
     *
     * `placements = insides + leaves`. Published rather than left to be inferred
     * because on an ordinary library it is most of the rows, and a figure over a
     * third of a kind's places should say so where it is.
     */
    readonly leaves: number;
    /** Placements bearing parts that a window could speak for. */
    readonly verdicts: number;
    /** Placements bearing parts that no row named, and therefore excluded. */
    readonly unknown: number;
    /**
     * Placements with a verdict that no reader reached.
     *
     * In neither term, because a reader who never got there says nothing about
     * what readers do once they have. It is the reason a kind can have verdicts
     * and still no share.
     */
    readonly unmet: number;
    /**
     * Placements at the root of their page.
     *
     * A root's `engaged` is the page-wide headcount of readers who did anything at
     * all, so a row whose placements are roots is that figure and not a
     * fact about a component. A kind is not a node and the same type is a root on
     * one page and nested on another, so nothing is excluded for it — this is the
     * number that says how much of the row is page-wide.
     */
    readonly roots: number;
    /**
     * Placements by the standing a page's own reading gives them, over
     * **every** placement including the leaves.
     *
     * The *places* half of this row, and the one a surface must not print under
     * the share's label: *readers acted in it in 3 of its 9 places* and *3 in 10
     * of the readers who met it acted inside it* are different sentences about one
     * component and can differ by an order of magnitude. It is the pairing care
     * the other two readings of a library already needed once.
     */
    readonly standings: Readonly<Record<ActionStanding, number>>;
    /** Revisions bearing a placement with an inside and a verdict. */
    readonly pages: number;
    /**
     * Of those, the pages that contributed reach — the weights that actually
     * decide the share.
     *
     * 1 is the scale-free case: one page's own sound figure, needing no door row.
     * It is also what makes the door's silences conditional, since a page nobody
     * reached needs no scale.
     */
    readonly weighed: number;
    /**
     * Page views that reached an enterable place of this kind, at the door's
     * scale: `reached × min(appearances, opened) ÷ appearances`, added over the
     * bearing placements.
     *
     * The denominator of {@link share}. **Not a count of people and deliberately
     * not rounded into one**: the unit is the pair *(a page view, a place
     * this kind stands on that page)*, so a page view of a page bearing three
     * placements is three of them.
     *
     * `null` under a silence, and `null` on a scale-free row — where the share
     * stands and there is no number on the door's scale to publish beside it.
     */
    readonly met: number | null;
    /** The same page views whose reader acted inside the place, at the same scale. */
    readonly acted: number | null;
    /** `met − acted`: the page views that met an enterable place and did nothing in it. */
    readonly ignored: number | null;
    /**
     * `acted ÷ met` — the share of the readers who met it that did something
     * inside it.
     *
     * A weighted mean of each page's own sound share with that page's arrivals
     * behind it, and the one figure here that survives where the counts do not:
     * a scale-free row publishes this and no count. Above 1 exactly where
     * {@link unreconciled} is non-nought and never otherwise.
     */
    readonly share: number | null;
    /**
     * Whether {@link met} and {@link acted} are on the door's scale, which is the
     * only scale two rows' counts may be compared on.
     *
     * False on a scale-free row and under a silence. {@link share} is sound either
     * way, which is the whole of what the door buys here.
     */
    readonly onDoorScale: boolean;
    /**
     * Appearances in excess of openings across the weighing pages, added **once
     * per page** rather than once per placement.
     *
     * The weights here are a page's and not a placement's, which is where this
     * parts from the reach reading's figure of the same name. It biases nothing:
     * the straddle divided out inside each page's share before the pages met, so
     * this is the measured size of a correction that has already happened.
     */
    readonly drift: number;
    /**
     * Openings across the weighing pages whose reading no rollup has folded yet.
     *
     * The one error left in the share, and it is in the weights rather than in any
     * term: a lagging page weighs less than a caught-up one, which shifts the
     * evidence and not the figure.
     */
    readonly pending: number;
    /**
     * No opening is waiting to be folded and nothing is unreconciled, so the
     * weights are final.
     *
     * **Not an exactness claim and there is no `exact` here**, because no term of
     * this share carries a straddle to be exact about. False under a silence.
     */
    readonly settled: boolean;
…

type LibraryAction = {
    /**
     * Every type that stands anywhere, most readers ignored first.
     *
     * Then the lower share, then by type, so two kinds that are ignored equally
     * do not reorder on a refresh. A kind with no share sorts after one whose
     * share is nought.
     */
    readonly byType: readonly KindAction[];
    /** Every role in the vocabulary, then the row for parts whose type declared none, in the same order. */
    readonly byRole: readonly KindAction[];
    /** Readings counted, which is revisions of pages and not trees. */
    readonly pages: number;
    /** Distinct trees across them. */
    readonly trees: number;
    /** Element nodes across them, which is the sum of every type row's placements. */
    readonly placements: number;
    /** Of those, the ones bearing element parts. */
    readonly insides: number;
    /** Of those, the ones with nothing inside them. `placements = insides + leaves`. */
    readonly leaves: number;
    /**
     * Page views counted at the door across the pages read, added **once per
     * page**.
     *
     * Addable for the reason no other count here is: a page view began on one
     * revision of one tree and was counted once. It is the weight behind
     * the whole reading and is the denominator of nothing.
     */
    readonly arrivals: number;
    /** Placements by standing, over the whole library. */
    readonly standings: Readonly<Record<ActionStanding, number>>;
    /**
     * The type the most readers met and did nothing inside, which is the kind to
     * look at first.
     *
     * By the **count** of page views and not by the share, for the reason a page's
     * falls are ranked by the readers they lose. A type and never a role,
     * because a type is the thing an author can replace.
     *
     * **A kind that is only ever a page's root is not eligible**, which is how a
     * page's own reading treats its root and the pace reading before it
     *: a root's reach is the whole page's, so such a row contains every row
     * it would outrank and would lead with *readers opened your pages and did
     * nothing* for ever. It is the row's `roots` against its `placements` that
     * decides, never the type's name — a kind is not a node, and a type that is a
     * root on one page and a band on another is a fact about a component and stays
     * in the ranking with {@link KindAction.roots} saying how much of it is
     * page-wide.
     *
     * It can only ever be a row on the door's scale, since a count is the thing
     * being ranked. {@link unranked} is how many rows had a share the ranking
     * could not see.
     */
    readonly mostIgnored: KindAction | null;
    /**
     * Type rows with a share and no count, which the ranking above cannot
     * include.
     *
     * The scale-free rows, and only those: a row the ranking passes over for being
     * a page's root is excluded by design rather than for want of a scale.
     * Published because a ranking that silently skipped rows is the kind of
     * omission a surface presents as a complete answer.
     */
    readonly unranked: number;
    /** Pages the door could scale, which is where every count here comes from. */
    readonly scaled: number;
    /**
     * The pages bearing a measured placement that the door could not scale, by
     * tree and newest revision first, with the reason in the vocabulary a page's
     * own reading publishes.
     *
     * One of these pages is why a row above is withheld — or is harmless, because
     * a page needs no scale until a second one is weighed against it. Reused from
     * the reach reading rather than restated: it is a fact about a page either way.
     */
    readonly unscaled: readonly UnscaledPage[];
    /**
     * The pages holding actions that credit nobody, by tree and newest revision
     * first.
     *
     * The sender diagnosis, and the actionable half of every `unwalked` row above.
     * Empty is the healthy state, and so is a deployment nobody acted on at all —
     * a page with no occurrences is not in this list.
     */
    readonly unwalked: readonly RevisionOf[];
    /**
     * Readings of a revision beyond the first, which were dropped.
     *
     * A caller that concatenated two reads holds one page twice, and a page twice
     * is the one way a weighted figure can lie about how much weight is behind it.
     */
    readonly duplicated: number;
    /**
     * Door rows for one revision beyond the first, which were ignored.
     *
     * A store keeps one row per revision, so this is a caller's two reads again —
     * and adding them would double a page's weight against every other page.
     */
    readonly duplicatedRows: number;
    /**
     * Types whose readings disagreed about the role they play, where the first
     * reading's answer stands.
     *
     * Detected off the same readings by the same rule as the other two library
     * readings, so the three cannot disagree about it.
     */
    readonly roleDisagreed: readonly PrimitiveType[];
};

type KindChange = {
    readonly kind: KindKey;
    /**
     * What part a type plays, or `null`. Always `null` on a role row, which
     * carries it as its key.
     *
     * The later window's answer where it stands there, so that a surface reading a
     * row and the role beside it is reading today's library.
     */
    readonly role: PrimitiveRole | null;
    /** Places of this kind that stand in both windows: the same node of the same page, of this kind on both sides. */
    readonly places: number;
    /** Places of it in the later window with no counterpart in the earlier one. */
    readonly gained: number;
    /** Places of it in the earlier window with no counterpart in the later one. */
    readonly lost: number;
    /**
     * Of {@link places}, those with a verdict on **both** sides, which is the
     * denominator of both shares.
     *
     * One number and not two, which is the whole of why the two shares are
     * comparable: a place nothing can be said about in either window is in neither
     * term, so the two sides are read over exactly the same set of places.
     */
    readonly comparable: number;
    /** Comparable places skipped in the earlier window and read in the later one. */
    readonly tookUp: number;
    /** Comparable places read in the earlier window and skipped in the later one. */
    readonly fellAway: number;
    /** Comparable places read in both. */
    readonly keptRead: number;
    /** Comparable places skipped in both. */
    readonly keptSkipped: number;
    /**
     * The share of {@link comparable} places that was read in the earlier window;
     * `null` where {@link silence} says why not.
     *
     * *At least one reader reached it*, which is what a standing of `read` means
     * and not what a person reads the word as. Places and never people: see
     * the module documentation and `library.ts`, where the same figure is taken of
     * one window.
     */
    readonly readShareWas: number | null;
    /** The same share in the later window, over the same places. */
    readonly readShareNow: number | null;
    readonly movement: KindMovement;
    /**
     * Why the two shares are not there, and `null` where they are.
     *
     * About the comparison and not about the row: {@link places},
     * {@link gained} and {@link lost} are counts of parts of trees and are true
     * whatever any window measured, which is how a census publishes a standing
     * beside a withheld share.
     */
    readonly silence: KindChangeSilence | null;
};

type LibraryChange = {
    /**
     * Every type that stands in either window, most places fallen away first.
     *
     * Then the lower read share in the later window, then by type, so two kinds
     * that lost the same number of places do not reorder on a refresh.
     */
    readonly byType: readonly KindChange[];
    /**
     * Every role in the vocabulary that stands in either window, then the row for
     * parts whose type declared none, in the same order as {@link byType}.
     *
     * Thin today for the reason every role figure in this subsystem is thin:
     * nothing in `src/primitives/` declares one, so nearly every part is in the
     * `null` row — and in this reading that row is the one that treats a node
     * whose type changed as a place still standing. The join is at read time
     *, so the day a role is declared these rows start answering without a
     * migration.
     */
    readonly byRole: readonly KindChange[];
    /** Forms read in both windows: a page in one of its forms, never a revision. */
    readonly pages: number;
    /** Forms read in the later window only, which is not pages published. */
    readonly pagesGained: number;
    /** Of {@link pagesGained}, forms whose page the earlier window already held. */
    readonly formsGained: number;
    /** Forms read in the earlier window only, which is not pages withdrawn. */
    readonly pagesLost: number;
    /** Of {@link pagesLost}, forms whose page the later window still holds. */
    readonly formsLost: number;
    /** The audiences each window's forms named, published and never refused. */
    readonly audiences: ComparedPopulations;
    /**
     * Paired pages whose revision moved between the windows.
     *
     * The comparison still stands — a placement is paired by node, and whether
     * readers reached it is a fact about the place either way — but it says that
     * the pages changed as well as the window, which is the difference between
     * *your readers behave differently* and *you changed your pages*. A reading
     * where this is nought is two windows of one library.
     */
    readonly republished: number;
    /** Places that stand in both windows, which is the sum of every type row's {@link KindChange.places}. */
    readonly placements: number;
    /** Places in the later window only. */
    readonly gained: number;
    /** Places in the earlier window only. */
    readonly lost: number;
    /**
     * Paired nodes whose primitive type changed.
     *
     * A place one kind left and another took, counted in the first's {@link
     * KindChange.lost} and the second's {@link KindChange.gained} — and held
     * still in the role rows where the two types play the same part. Not an
     * alarm: it is the commonest change an author makes to a library.
     */
    readonly recast: number;
    /**
     * A floor on the page views of the earlier window, added over the paired
     * pages.
     *
     * `PageReading.views` is the largest `views` any one part of a page reports,
     * which is a floor and not a count. Published because every transition
     * in this reading is confounded by it: a quieter window skips more places with
     * no reader behaving differently, and these two numbers are what let somebody
     * see that before reading a movement as a finding.
     *
     * Not a count of readers, and not addable into one: a reader who read two
     * pages is two page views here.
     */
    readonly viewsWas: number;
    /** The same floor for the later window, over the same pages. */
    readonly viewsNow: number;
    /**
     * The type that lost its reading in the most places, which is the kind to look
     * at first.
     *
     * By the **count** of places and not by the share, for the reason a page's
     * falls are ranked by the readers they lose and a census's kinds by the
     * places they are skipped in: a kind that lost its one and only place
     * is a perfect rate and a smaller problem than one that lost seven of nine.
     * `null` where nothing anywhere fell away.
     *
     * A type and never a role, because a type is the thing an author can replace.
     */
    readonly mostAbandoned: KindChange | null;
    /** The type that gained its reading in the most places, by the same rule. */
    readonly mostTakenUp: KindChange | null;
    /**
     * Forms read at two revisions in one window, which are in nothing above.
     *
     * A page that is two live revisions in one window has no single counterpart in
     * the other, and the comparison pairs by page in its form. See the module
     * documentation: excluded and named rather than picked between.
     *
     * A **form** and not a tree, because a page served in two forms is two
     * paired pages here: one of them held at two revisions says nothing about the
     * other, and a screen naming the exclusion needs to say which form it was.
     */
    readonly ambiguous: readonly PageForm[];
    /**
     * Readings of a revision beyond the first, on either side, which were dropped.
     *
     * A caller that concatenated two reads of one window holds a page twice, and a
     * page twice is the one way a census — or a comparison of two — can lie about
     * how much of a library there is.
     */
    readonly duplicated: number;
    /**
     * Types the two windows disagree about the role of, where the later window's
     * answer stands.
     *
     * A type plays one part, so a disagreement is not a change a deployment
     * made: it is two readings joined against two different registries, held
     * against each other. Every role row below is then about neither.
     */
    readonly roleDisagreed: readonly PrimitiveType[];
};

type PairedWindow = {
    /**
     * The window's readings, one per form, keyed by the published form rule.
     *
     * Keyed by the **form** and not by the tree, because two forms of one page
     * share a tree and have separate counterparts in the other window.
     * Keyed by a tree, the second form of a page at one revision was dropped as
     * the first one handed in twice, which is the double count nothing can notice
     * afterwards, and two forms at two revisions gated **both** out as
     * ambiguous.
     */
    readonly byForm: ReadonlyMap<string, PageReading>;
    /**
     * Forms held at two revisions, which have no single counterpart in the other
     * window.
     *
     * A map rather than a set so that the form can be published back to a surface
     * that has to name the page it excluded: the key is opaque and a screen needs
     * the tree and the audience.
     */
    readonly ambiguous: ReadonlyMap<string, PageForm>;
    /** The same revision of the same form handed in again. */
    readonly duplicated: number;
    /**
     * The audiences this window's forms named, in a stable order.
     *
     * `[]` is *no form here named one*, which is every window written before the
     * column existed and every one a test builds by hand. Two members is
     * a deployment serving two forms of at least one of its pages and is
