    /** The type that gained the most readers, by the same rule. */
    readonly mostTakenUp: KindReachChange | null;
    /**
     * Forms read at two revisions in one window, which are in nothing above.
     *
     * A page that is two live revisions in one window has no single counterpart in
     * the other, and the comparison pairs by page in its form: excluded and
     * named rather than picked between. A form and not a tree, because two forms
     * of a page are two paired pages and one of them being ambiguous says
     * nothing about the other.
     */
    readonly ambiguous: readonly PageForm[];
    /** Readings of a revision beyond the first, on either side, which were dropped. */
    readonly duplicated: number;
    /**
     * Door rows for one revision beyond the first, across the pages of both
     * windows, which were ignored.
     *
     * A store keeps one row per revision, so this is a caller's two reads — and
     * adding them would double a page's arrivals and halve every share taken
     * against it. Counted over every page read rather than only the paired ones,
     * because it is an alarm about the caller and not a term in any figure.
     */
    readonly duplicatedRows: number;
    /** Types the two windows disagree about the role of, where the later window's answer stands. */
    readonly roleDisagreed: readonly PrimitiveType[];
};

const weightMovedOver: (weights: readonly {
    readonly was: number;
    readonly now: number;
}[], totals: {
    readonly was: number;
    readonly now: number;
}) => number | null

type ScaledPage = {
    readonly reading: PageReading;
    readonly door: PageDoor;
    readonly duplicatedRows: number;
};

type LibrarySide = {
    readonly pages: PairedWindow;
    /**
     * Each paired page's door, under the same key the pairing uses.
     *
     * Keyed by the form rather than by the tree because the door is per form too:
     * `pageViewsFor` scopes a page-view row to the reading's own audience,
     * so two forms of one page have two doors and a map keyed by the tree would
     * hold one of them and scale both sides of the other against it.
     */
    readonly scaled: ReadonlyMap<string, ScaledPage>;
    readonly duplicatedRows: number;
};

type ReaderWords = {
    /**
     * Passages both revisions say word for word, across the places of this kind
     * that stand in both windows.
     *
     * The count and not the word total is what says whether there is anything to
     * compare, because a passage may hide every word it has.
     */
    readonly passages: number;
    /** The words those passages say, which is the mass this reading is about. */
    readonly carried: number;
    /**
     * Of {@link passages}, those with a verdict on **both** sides, which is the
     * set every figure below is taken over.
     *
     * One number and not two, which is what makes the two levels comparable: a
     * passage nothing can be said about in either window is in neither mass, so
     * the two sides are read over exactly the same text.
     */
    readonly spoken: number;
    /** The words those passages say: the universe of both masses. */
    readonly comparable: number;
    /** Carried words `unknown` on one side or the other, which are in no mass. */
    readonly unspoken: number;
    /**
     * Comparable passages whose word count is a floor, because the part saying
     * them declares no `copy`.
     *
     * Non-nought is what withholds every difference here and leaves the two
     * levels standing as floors. **A count of passages and not of words**,
     * because the commonest floor of all is a part that declares no `copy` at
     * all and whose visible words are therefore nought: a trigger counted in
     * words would miss exactly the case it exists for.
     */
    readonly floored: number;
    /** The visible words in those passages, which is the part of the mass that is certain. */
    readonly flooredWords: number;
    /**
     * Page views at the door's scale across the pages bearing a comparable word
     * of it, in the earlier window, added **once per page**.
     *
     * The denominator of {@link typicalWas} and the weight behind it.
     */
    readonly countedWas: number | null;
    /** The same for the later window. */
    readonly countedNow: number | null;
    /**
     * Reader-words in the earlier window at the door's scale:
     * `Σ readers × words` per page, scaled by `counted ÷ appearances`.
     *
     * **Not a count of people and deliberately not rounded into one**.
     */
    readonly reachedWas: number | null;
    /** The same for the later window. */
    readonly reachedNow: number | null;
    /**
     * `reachedWas ÷ countedWas` — the carried words the typical reader who met it
     * reached, in the earlier window.
     *
     * A floor under a floor, and exact otherwise. `null` where a silence says why
     * there is none.
     */
    readonly typicalWas: number | null;
    /** The same in the later window, over the same words. */
    readonly typicalNow: number | null;
    /** `typicalNow − typicalWas`, in words per reader. Withheld under a floor. */
    readonly shift: number | null;
    /**
     * The movement stated at the later window's scale: `shift × countedNow`.
     *
     * Reader-words and never people, exactly as {@link reachedNow} is — the
     * figure this reading ranks by, for the reason a page's falls are ranked by
     * the readers they lose.
     */
    readonly wordsMoved: number | null;
    /**
     * The later window's per-page rates at the earlier window's weights: the
     * words there would have been if no page's traffic had moved.
     *
     * Isolates the readers. Withheld under a floor, because the only use of a
     * counterfactual is a subtraction.
     */
    readonly ifTrafficHeld: number | null;
    /**
     * The earlier window's per-page rates at the later window's weights: the
     * words there would have been if no reader had read differently.
     *
     * Isolates the mix of pages.
     */
    readonly ifReadingHeld: number | null;
    /**
     * How far the weights moved: half the sum of the absolute movements in each
     * page's share of its side's total weight, in `[0, 1]`.
     *
     * The arithmetic a comparison of two readerships uses, over pages
     * rather than regions. **Published and never judged**, and published under a
     * floor as well, because there is no word in it.
     *
     * `null` is withheld with the rest of the row, and only that: a measured row
     * banked a page whose two doors both spoke, so the distance is a number
     * wherever this roll publishes figures at all.
     */
    readonly weightMoved: number | null;
    /** Appearances in excess of openings in the earlier window, over the weighted pages. */
    readonly driftWas: number;
    /** The same for the later window. */
    readonly driftNow: number;
    /** Openings in the earlier window, over the weighted pages, whose reading no rollup has folded. */
    readonly pendingWas: number;
    /** The same for the later window. */
    readonly pendingNow: number;
    /**
     * Comparable passages reporting more readers than their page had appearances,
     * on either side, which no rollup produces.
     *
     * Node counters older than the page-view column, or a caller that
     * concatenated two reads. A surface should show the words comparison
     * instead where it is non-nought.
     */
    readonly unreconciled: number;
    /**
     * Nobody's visit spanned a window on either side, nothing is waiting to be
     * folded, nothing is unreconciled and no word is a floor — so both levels are
     * exact.
     *
     * False under any silence. It says nothing about the weights: a comparison
     * can be exact on both sides and still be weighted differently, which is what
     * {@link weightMoved} is for.
     */
    readonly exact: boolean;
};

type KindWordReachChange = {
    readonly kind: KindKey;
    /**
     * What part a type plays, or `null`. Always `null` on a role row,
     * which carries it as its key.
     *
     * The later window's answer where it stands there, so that a surface reading
     * a row and the role beside it is reading today's library.
     */
    readonly role: PrimitiveRole | null;
    /** Places of this kind that stand in both windows: the same node of the same page, of this kind on both sides. */
    readonly places: number;
    /** Places of it in the later window with no counterpart in the earlier one. */
    readonly gained: number;
    /** Places of it in the earlier window with no counterpart in the later one. */
    readonly lost: number;
    /**
     * Places of it held still whose text the change rewrote, which are in no mass.
     *
     * A word-weighted figure needs one word count and these have two. Published
     * rather than dropped, because *this kind was rewritten everywhere* is why a
     * row is `wordless` and is the answer somebody most needs.
     */
    readonly rewritten: number;
    /**
     * Pages bearing a comparable word of it, which is **forms** and not
     * revisions.
     *
     * A page served in two forms is two of them, for the reason the
     * pairing counts it as two: two forms have two doors, two sets of readers and
     * two masses, and a kind whose words are carried in both is carried in both.
     */
    readonly pages: number;
    readonly words: ReaderWords;
    readonly movement: KindWordReachMovement;
    /** Which side was sufficient, or `null` where the figure did not move or is withheld. */
    readonly cause: ReaderShareCause | null;
    /**
     * Why the figures are not there, and `null` where they are.
     *
     * About the comparison and not about the row: {@link places},
     * {@link gained} and {@link lost} are counts of parts of trees and are true
     * whatever any window measured, which is how a census publishes a standing
     * beside a withheld share.
     */
    readonly silence: KindWordReachChangeSilence | null;
};

type LibraryWordReachChange = {
    /**
     * Every type that stands in either window, most reader-words lost first.
     *
     * Then the lower figure in the later window, then by type, so two kinds that
     * lost the same do not reorder on a refresh.
     */
    readonly byType: readonly KindWordReachChange[];
    /**
     * Every role in the vocabulary, then the row for parts whose type declared
     * none, in the same order as {@link byType}.
     */
    readonly byRole: readonly KindWordReachChange[];
    /**
     * The whole library's carried words, added across every kind exactly once.
     *
     * The figure a comparison of readers cannot have: a page's words
     * partition across its parts exactly once, so adding every kind's words reads
     * no sentence twice, while adding every kind's places would count a page once
     * per element node. A recast place is in no kind's carried words and is in
     * none of these either — it is a place one kind left and another took.
     *
     * There is no movement and no silence here on purpose. Every reason published
     * by this reading is about one kind of part, and a reason about the whole
     * would be a second subject on one vocabulary.
     */
    readonly words: ReaderWords;
    /** Forms read in both windows: a page in one of its forms, never a revision. */
    readonly pages: number;
    /** Forms read in the later window only, which is not pages published. */
    readonly pagesGained: number;
    /** Of {@link pagesGained}, forms whose page the earlier window already held. */
    readonly formsGained: number;
    /** Forms read in the earlier window only, which is not pages withdrawn. */
    readonly pagesLost: number;
    /** Of {@link pagesLost}, forms whose page the later window still holds. */
    readonly formsLost: number;
    /** The audiences each window's forms named, published and never refused. */
    readonly audiences: ComparedPopulations;
    /**
     * Paired pages whose revision moved between the windows.
     *
     * The comparison still stands — a placement is paired by node and a passage
     * by its text — but it says the pages changed as well as the window.
     */
    readonly republished: number;
    /** Places that stand in both windows, of the same type on both sides. */
    readonly placements: number;
    /** Places in the later window only. */
    readonly gained: number;
    /** Places in the earlier window only. */
    readonly lost: number;
    /** Paired nodes whose primitive type changed: a place one kind left and another took. */
    readonly recast: number;
    /** Places held still whose text the change rewrote, across every kind once. */
    readonly rewritten: number;
    /**
     * Page views counted at the door across the paired pages in the earlier
     * window, added once per page.
     *
     * The weight behind the whole comparison — *this moved among six hundred
     * readers rather than six* — and the denominator of nothing.
     */
    readonly arrivalsWas: number;
    /** The same for the later window. */
    readonly arrivalsNow: number;
    /** Paired pages the door could scale in **both** windows, which is where every figure here comes from. */
    readonly scaled: number;
    /**
     * The paired pages bearing a comparable word that the door could not scale,
     * by tree, newest revision first, with the side they are on.
     *
     * The actionable half of every door silence on a row above. Empty is the
     * healthy state.
     */
    readonly unscaled: readonly UnscaledSide[];
    /**
     * The type that lost the most reader-words, which is the kind to look at
     * first.
     *
     * By {@link ReaderWords.wordsMoved} and not by the figure, which is this
     * subsystem's ranking rule everywhere: a kind the typical reader
     * reads two words less of across a thousand readers is a bigger fact than one
     * they read fifty words less of across three. A type and never a role,
     * because a type is the thing an author can replace.
     */
    readonly mostAbandoned: KindWordReachChange | null;
    /** The type that gained the most reader-words, by the same rule. */
    readonly mostTakenUp: KindWordReachChange | null;
    /**
     * Forms read at two revisions in one window, which are in nothing above.
     *
     * A page that is two live revisions in one window has no single counterpart
     * in the other, and the comparison pairs by page in its form. A form
     * and not a tree, because two forms of a page are two paired pages and
     * one of them being ambiguous says nothing about the other.
     */
    readonly ambiguous: readonly PageForm[];
    /** Readings of a revision beyond the first, on either side, which were dropped. */
    readonly duplicated: number;
    /**
     * Door rows for one revision beyond the first, across the pages of both
     * windows, which were ignored.
     *
     * A store keeps one row per revision, so this is a caller's two reads — and
     * adding them would double a page's arrivals and halve every figure taken
     * against it.
     */
    readonly duplicatedRows: number;
    /** Types the two windows disagree about the role of, where the later window's answer stands. */
    readonly roleDisagreed: readonly PrimitiveType[];
};

type FieldSubject =
/** The part of the page the observation is about. */
"part"
/** Which page, which revision of it, and which form was served. */
 | "page"
/** What was observed about the part — when, how long, open or closed. */
 | "observation"
/**
 * The one visit the delivery belongs to.
 *
 * The narrowest scope anything here is correlated at, and the only one about
 * a visit rather than about a page.
 */
 | "page-view"
/** The delivery itself — when it was sent, and what it carried. */
 | "delivery";

type CollectedField = {
    /** The field's name in the delivery, which is what a reader comparing this to a payload sees. */
    readonly field: string;
    /** What it is about. */
    readonly subject: FieldSubject;
    /** One sentence, addressed to the reader. */
    readonly says: string;
};

const SIGNAL_FIELDS: {
    readonly [Kind in ReaderSignalKind]: FieldsOf<Extract<ReaderSignal, {
        kind: Kind;
    }>>;
}

type Refusal = 
/**
 * No identifier for a person or a device, and nothing standing in for one.
 *
 * The first clause of rule 1. The second half of the sentence is the half
 * that matters to somebody who has read a privacy policy before: an
 * identifier nobody set is still an identifier.
 */
"no-identifier"
/** No signature derived from a device, a browser or its settings. */
 | "no-fingerprint"
/** Nothing the page said to you and nothing you said to it. */
 | "no-content"
/** No cursor, no scroll trace, no recording. */
 | "no-pointer-path"
/** Nothing that joins one visit to another. */
 | "no-stitching"
/** Nothing derived from your address outlives the request it arrived on. */
 | "no-address";

type RegionNotice = {
    /**
     * The page views a country needs before it is published at all, or `null`
     * where no country is read.
     *
     * `null` is *nothing about where you are is read*, which is a different
     * sentence from *your country is counted and will not be published until
     * enough others share it* — and the difference is the whole of what a floor
     * is for. A country with a handful of views in it is a person (§7).
     */
    readonly floor: number | null;
};

type CollectionNotice = {
    /** The kinds this configuration broadcasts, in the vocabulary's order. */
    readonly collects: readonly CollectedKind[];
    /** What travels with every delivery. */
    readonly delivery: readonly CollectedField[];
    /** What is never collected, whatever else is configured. */
    readonly refuses: readonly Refusal[];
    /** Where readers are counted from, or that they are not. */
    readonly region: RegionNotice;
    /**
     * How long a delivery itself lives before it is counted and dropped, in
     * milliseconds.
     *
     * The deployment's own number (`collect.ts`), and the honest bound on the
     * life of the page-view key, since the key exists in the buffer and nowhere
     * else. **The framework cannot promise the moment it is swept**, because a
     * host schedules the sweep: this is the age at which a delivery becomes ripe,
     * not a guarantee about when the next run happens.
     * {@link describeBuffer} says both halves.
     */
    readonly bufferMs: number;
};

type CollectedKind = {
    readonly kind: ReaderSignalKind;
    /** What the page observed, addressed to the reader. */
    readonly observes: string;
    /** Every field that kind carries, including the ones it sometimes omits. */
    readonly carries: readonly CollectedField[];
};

type NoticeRequest = {
    /**
     * The options the page is broadcast with — the same object, so that a notice
     * and the page it is about cannot disagree about which kinds are reported.
     *
     * Only `kinds` is read. `types` and `within` narrow collection below what the
     * notice says, which is the ceiling rule above.
     */
    readonly page?: Pick<ReaderSignalOptions, "kinds">;
    /**
     * The window the deployment collects on, from its own `CollectionRequest`
     * (`collect.ts`). The default when absent.
     *
     * Reported as given rather than clamped: `collect.ts` is what refuses a
     * window below its minimum, and a notice that silently reported a different
     * number from the one a deployment configured would be a second rule about
     * one setting.
     */
    readonly windowMs?: number;
    /**
     * The region counting this deployment's intake does, where it does any.
     *
     * Absent is *no country is read*, which is the default: reading one is
     * something an intake is configured to do (§7). A floor below the published
     * minimum is raised to it, by the same helper the region map itself uses.
     */
    readonly region?: {
        readonly floor?: number;
    };
};

type PaceStanding = 
/**
 * Readers had less than {@link SKIMMED_BELOW} of the time the words take.
 *
 * The one verdict here that is safe against every bias in the module
 * documentation, and the one a screen should lead with.
 */
"skimmed"
/** Time enough for the words, and not conspicuously more. */
 | "paced"
/** More than {@link LINGERED_ABOVE} times the time the words take. */
 | "lingered"
/** Nothing can be said, and {@link PacedPart.silence} says which nothing. */
 | "unknown";

type PacedPart = {
    readonly nodeId: NodeId;
    readonly type: PrimitiveType;
    /** What part it plays, or `null` where its type declared none. */
    readonly role: PrimitiveRole | null;
    /** 0 at the root. */
    readonly depth: number;
    /** null at the root. */
    readonly parentId: NodeId | null;
    /** Distinct page views that reported it coming into view; `0` where no row named it. */
    readonly readers: number;
    /** The words this part says itself, counted. Its own, never its subtree's. */
    readonly words: number;
    /**
     * The words of this part and everything under it.
     *
     * The denominator, because the text on screen while a band was up is the
     * band's and its children's. Nests, and is therefore never added across parts.
     */
    readonly wordsWithin: number;
    /**
     * Whether {@link wordsWithin} is a floor rather than a count.
     *
     * True when anything in the subtree declared no `copy`, or declared a prop
     * holding something other than a string.
     */
    readonly floored: boolean;
    /** Time on screen, summed across every view in the window. */
    readonly dwellMs: number;
    /**
     * The same time per reader, after {@link PaceOptions.inflation}.
     *
     * `null` where nobody reached it. Generous by the two biases nothing measures:
     * dwell counts a part that was merely up, and an ancestor's dwell covers its
     * children's reading.
     */
    readonly spentMs: number | null;
    /** What {@link wordsWithin} takes at the costing rate. `0` where it says nothing. */
    readonly needMs: number;
    /**
     * Time spent for every unit of time the words take. `1` is exactly enough.
     *
     * `null` where there is nothing to divide: no reader, or no words.
     */
    readonly pace: number | null;
    readonly standing: PaceStanding;
    /** Why there is no verdict, and `null` where there is one. */
    readonly silence: PaceSilence | null;
    /**
     * Readers times the words they were shown here — the ranking key, and a
     * magnitude rather than a census.
     *
     * Nests like {@link wordsWithin} does, so it ranks and is never summed.
     */
    readonly wordsPassed: number;
};

type PagePace = {
    readonly treeId: TreeId;
    readonly revision: number;
    /** The page's view floor, carried through from the reading unchanged. */
    readonly views: number;
    /** Every element part of the revision, in reading order. */
    readonly parts: readonly PacedPart[];
    readonly standings: Readonly<Record<PaceStanding, number>>;
    /** Why the parts with no verdict have none. Counts only the silent ones. */
    readonly silences: Readonly<Record<PaceSilence, number>>;
    /**
     * The root, judged against the whole page.
     *
     * *Readers spend a third of the time this page's words take* is a true
     * sentence and the one a reader screen opens with — and it is kept out of
     * {@link mostSkimmed} because the page contains every part, so by words passed
     * it would win every ranking it was entered in.
     *
     * `null` where the revision's root is not an element, which is the one tree
     * shape with no part at depth 0.
     */
    readonly whole: PacedPart | null;
    /**
     * The part of the page most words went unread in: most words passed, then
     * first in reading order.
     *
     * By words passed rather than by the lowest pace, for the same reason a stop
     * is ranked by the readers it loses: a caption two readers hurried
     * past is a worse ratio and a smaller problem than a band four hundred of
     * them did.
     */
    readonly mostSkimmed: PacedPart | null;
    /** The inflation that was applied; `0` when none was given. */
    readonly inflation: number;
    /** The costing rate that was applied, which is the default unless one was given. */
    readonly wordsPerMinute: number;
};

type PaceHeld = {
    /** `null` where there is nothing to divide: no reader on the side the time came from, or no words on the side the words came from. */
    readonly pace: number | null;
    /**
     * The verdict that pace carries, under **either** side's floor.
     *
     * A floor is taken from both sides because a counterfactual's two terms come
     * from two revisions, and words nobody counted on either one are words
     * missing from this ratio. The conservative reading, which leaves it
     * `unknown` rather than claiming the weaker verdicts.
     */
    readonly standing: PaceStanding;
};

type ComparedPace = {
    readonly nodeId: NodeId;
    /** The later revision's type, which is the page somebody is looking at. */
    readonly type: PrimitiveType;
    /** The later revision's role, or `null` where its type declared none. */
    readonly role: PrimitiveRole | null;
    /** The whole of what the earlier window said about it. */
    readonly was: PacedPart;
    /** The whole of what the later window said about it. */
    readonly now: PacedPart;
    readonly movement: PaceMovement;
    /**
     * `now.pace ÷ was.pace`, with the reason named where there is no quotient
     *.
     *
     * Exactly {@link timeRatio} ÷ {@link needRatio}, which is the identity this
     * module is built on: a pace moves because readers' time moved, because the
     * words moved, or both. The identity holds over the quotients and not over
     * the absences: a part whose words were wordless then and are not now has no
     * pace to divide and three absences that do not multiply.
     */
    readonly paceRatio: Ratio;
    /**
     * `now.spentMs ÷ was.spentMs` — the readers' side of the division.
     *
     * Each term is a mean off one side's own row, so each side's straddle has
     * very nearly divided out before they meet. `unmeasured` where either side
     * had no reader, and `from-nothing` where the earlier window's readers spent
     * no measurable time at all.
     */
    readonly timeRatio: Ratio;
    /**
     * `now.needMs ÷ was.needMs` — the page's side of the division.
     *
     * Exact and reader-free: it is what the change did to the time this part's
     * words ask for. Below 1 is a part the change shortened, and `from-nothing`
     * is a part the earlier revision left wordless — which is a fact about the
     * change rather than about a window, and the one absence here no reader can
     * cause.
     */
    readonly needRatio: Ratio;
    /** The later window's time against the earlier revision's words — the readers alone. */
    readonly ifWordsHeld: PaceHeld;
    /** The earlier window's time against the later revision's words — the change alone. */
    readonly ifTimeHeld: PaceHeld;
    /** Which side the verdict moved with, and `null` where it did not move. */
    readonly cause: PaceCause | null;
};

type TimeCount = {
    readonly was: number;
    readonly now: number;
    readonly change: number;
};

type PaceChange = {
    /** The earlier reading's tree. The two agree unless `silence` is `different-trees`. */
    readonly treeId: TreeId;
    readonly revisions: {
        readonly was: number;
        readonly now: number;
    };
    /**
     * The audience each side was of, where its reading named one.
     *
     * As `ReadingChange.audiences` carries it, and for the same reason: a `null`
     * on either side is why an unprovable pair of populations is compared rather
     * than refused.
     */
    readonly audiences: ComparedAudiences;
    /** The two pace readings this comparison is made of. */
    readonly readings: {
        readonly was: PagePace;
        readonly now: PagePace;
    };
    /**
     * Every part both revisions have that says something on either side, in the
     * **later** reading order.
     *
     * The later order because that is the page somebody is looking at. A part
     * whose subtree says nothing on both sides and hides nothing on either is
     * left out altogether: it has no pace in any window, so a row for it would
     * only ever read `unknown` and would make {@link movements} a count of
     * spacers.
     */
    readonly compared: readonly ComparedPace[];
    /**
     * Parts only the later revision has, as it paced them, in its reading order.
     *
     * A census with readers in it rather than an exact one, unlike the census of
     * the words a change wrote: a part nobody could have read before still
     * has to be read now for anything to be said about it. *The change added a
     * band and readers are skimming it* is the row worth looking at.
     */
    readonly added: readonly PacedPart[];
    /** Parts only the earlier revision had, as it paced them, in its reading order. */
    readonly removed: readonly PacedPart[];
    /** Compared parts by what happened to the verdict. The five add to {@link compared}'s length. */
    readonly movements: Readonly<Record<PaceMovement, number>>;
    /**
     * The parts whose verdict moved, by what moved it. The five add to
     * `movements.eased + movements.rushed`.
     */
    readonly causes: Readonly<Record<PaceCause, number>>;
    /**
     * The root, compared against itself across the two revisions.
     *
     * *Readers had a third of the time this page's words take and now they have
     * half* — the page's one figure, and a row rather than an addition for the
     * reason the module documentation gives. Kept out of the rankings below,
     * because its subtree is every part it would outrank.
     *
     * `null` where either revision's root is not an element, or where the root
     * says nothing on both sides.
     */
    readonly whole: ComparedPace | null;
    /**
     * The part the change made most room to read: `eased`, most words passed
     * now, then first in the later reading order.
     *
     * By words passed — readers times the words they were shown — rather than by
     * the change in pace, which is the ranking rule a fall between two siblings
     * and a skimmed part already use: a caption two readers now have
     * time for is a better ratio and a smaller gain than a band four hundred of
     * them do.
     */
    readonly mostEased: ComparedPace | null;
    /** The part it cost most, on the same terms. */
    readonly mostRushed: ComparedPace | null;
    /**
     * The parts readers skimmed before and skim now, most words passed first,
     * then in the later reading order.
     *
     * The list a person can act on without reading anything else, and the one
     * ranking here that is about where a change did **not** land. The root is
     * left out, as it is left out of every ranking here, because its subtree is
     * every part it would outrank; {@link whole} carries it. `still-skimmed`
     * only: a part whose verdict is `unknown` on either side is in
     * {@link movements} where it can be seen and not acted on, because putting it
     * here would turn *nothing can be said* into *readers are not reading this*.
     */
    readonly stillSkimmed: readonly ComparedPace[];
    /**
     * What the two revisions ask of a reader who reads every word of them, before
     * and after.
     *
     * The root's `needMs` on each side, which is the page's whole text costed
     * once — not a sum over the parts, which would charge a reader once per level
     *. `null` where there is no {@link whole} to read it off.
     */
    readonly need: TimeCount | null;
    /** Why there is no comparison of the reading, or `null` where there is one. */
    readonly silence: PaceChangeSilence | null;
    /** The costing rate both sides were read at, which is the published default unless one was given. */
    readonly wordsPerMinute: number;
    /** The straddle correction applied to each side; `0` where none was given. */
    readonly inflation: {
        readonly was: number;
        readonly now: number;
    };
};

type PaceChangeOptions = {
    readonly inflation?: {
        readonly was?: number;
        readonly now?: number;
    };
    readonly wordsPerMinute?: number;
};

type RevisionViews = {
    readonly treeId: TreeId;
    readonly revision: number;
    readonly views: number;
};

type ReaderPageViews = {
    readonly treeId: TreeId;
    readonly revision: number;
    /**
     * Page views that *began* on this revision.
     *
     * Exact, in the sense that matters: counted once, at the instant a page view
     * opened, never recounted, and therefore addable across windows, revisions,
     * trees and months. The two things it is not exact against are worth knowing
     * — a sender that retries an opening delivery after the first one was kept
     * counts twice, and a count cannot be uncounted; and a sender is what
     * says it opened at all, so a page that lies inflates this the way it could
     * already inflate a region bucket. The rate limiter is what bounds both.
     */
    readonly opened: number;
    /**
     * The same page views as the rollups saw them: once per window each appeared
     * in.
     *
     * Which is why it is kept at all. On its own it is the count a rollup can
     * only approximate; beside `opened` it is the measurement of that
     * approximation, because the only way the two can differ for an honest sender
     * is a page view whose batches landed in more than one window.
     */
    readonly appearances: number;
};

type StoredPageViews = ReaderPageViews & {
    /** The audience these page views were served under. See `StoredTally.audienceId`. */
    readonly audienceId: AudienceId;
    /**
     * When either writer last moved this row.
     *
     * Written by the door on every delivery that opened a page view *and* by
     * every rollup that folded one, which is what makes it useless for telling a
     * stalled collection from a quiet one: a busy page whose rollup has stopped
     * keeps a fresh timestamp while its appearances never move again.
     */
    readonly updatedAt: string;
    /**
     * When a rollup last folded a window holding page views of this revision, or
     * absent where nothing attests a fold.
     *
     * **Absent is not *never folded*.** It is *nothing here can say*: a row
     * written before the column existed, a store a caller built by hand, a
     * fixture. The two cases are one state, no reading claims anything from it,
     * and the first fold after an upgrade fills it in.
     *
     * Where it *is* there, it is the one timestamp in this subsystem written by a
     * single writer, and therefore the only thing that can say an opening has
     * been pending longer than it should be.
     */
    readonly foldedAt?: string;
};

type PageViewReading = {
    /** Page views that began, across every row read. Exact, and addable. */
    readonly opened: number;
    readonly appearances: number;
    readonly drift: number;
    readonly pending: number;
    readonly inflation: number | null;
    /** Newest revision first, trees in id order, so a screen does not reorder on a refresh. */
    readonly revisions: readonly RevisionPageViews[];
};

type RevisionOf = {
    readonly treeId: TreeId;
    readonly revision: number;
    readonly audienceId?: AudienceId | null;
};

type RoleDeclarations = {
    readonly typesWithRole: (role: PrimitiveRole) => readonly PrimitiveType[];
};

type PartReading = {
    readonly nodeId: NodeId;
    readonly type: PrimitiveType;
    /** What part it plays, or `null` where its type declared none. */
    readonly role: PrimitiveRole | null;
    /** 0 at the root. */
    readonly depth: number;
    /** null at the root. */
    readonly parentId: NodeId | null;
    readonly standing: PartStanding;
    /**
     * The counters, or `undefined` where no signal in the window named it.
     *
     * Undefined is not zero and is kept apart from it on purpose. A part with a
     * row of zeroes was reported on; a part with no row was not, and the
     * difference is the whole of how `skipped` is told from a quiet page.
     */
    readonly counters: ReaderTally | undefined;
    /**
     * The words this part says itself: its declared copy props, and the text
     * handed to it directly or through a slot.
     *
     * **Its own, never its subtree's.** Neither a text node nor a slot node is an
     * element, so neither can ever be a part of its own and the words handed into
     * one would otherwise be lost; every other descendant is a part in this same
     * list. So the words of a page are
     * partitioned across its parts exactly once, and a caller may add two rows
     * together without reading a headline twice.
     *
     * `unread` and `unspoken` mean what they mean in the reading they come from
     *: nobody has said whether these props are words, and somebody said
     * these were words and what is in them is not one. The starter library
     * declares `copy` across itself, so `unread` on a page built from it
     * is a deployment's own primitives rather than the framework's silence.
     */
    readonly copy: NodeCopy;
};

type RoleReading = {
    /** `null` is the row for parts whose type declared no role, which is most of a page today. */
    readonly role: PrimitiveRole | null;
    /** Element nodes of this revision playing it. */
    readonly parts: number;
    readonly standings: Readonly<Record<PartStanding, number>>;
    readonly dwellMs: number;
    readonly activations: number;
    readonly opens: number;
    readonly closes: number;
    readonly completions: number;
};

type ReadingStep = {
    readonly nodeId: NodeId;
    readonly type: PrimitiveType;
    /** What part it plays, or `null` where its type declared none. */
    readonly role: PrimitiveRole | null;
    readonly standing: PartStanding;
    /**
     * Distinct page views that reported it coming into view, and `0` where no row
     * named it at all.
     *
     * Zero means two different things and {@link ReadingStep.anchors} is which:
     * nobody got here, or nothing can say.
     */
    readonly reached: number;
    /**
     * Whether this step can be either end of a stop.
     *
     * False for a part that reported something other than a view, whose `reached`
     * of 0 is an absence of evidence rather than an absence of readers.
     */
    readonly anchors: boolean;
};

type ReadingStop = {
    /** The part they reached. */
    readonly after: NodeId;
    /** The next part in the run that could anchor a stop, which fewer reached. */
    readonly before: NodeId;
    /** Views that reached `after`, which is the denominator of `share`. */
    readonly reached: number;
    /** Views that reached `after` and not `before`. */
    readonly lost: number;
    /**
     * `lost ÷ reached`, in `(0, 1]`.
     *
     * Both numbers are `reached` counts off the same rows, so this is the figure
     * that survives the over-count the counts themselves carry. It is never
     * divided by the page's views or by the page views counted at the door — those
     * are a different measurement of a different thing, and dividing across the
     * two would put a number on a screen that no two rows agree about.
     */
    readonly share: number;
};

type ReadingRun = {
    readonly parentId: NodeId;
    /** The depth of the steps, which is one below the parent's. */
    readonly depth: number;
    readonly steps: readonly ReadingStep[];
    /** Every fall, in run order. */
    readonly stops: readonly ReadingStop[];
    /**
     * The last step in run order that any view reached, or `null` where none did.
     *
     * *How far down they got*, as a node rather than a fraction.
     */
    readonly furthest: NodeId | null;
    /**
     * Pairs where more views reached the later part than the earlier one.
     *
     * Scrolling cannot do this, so it is a reader who arrived somewhere other than
     * the top — an anchored link, a restored scroll position — or a part that is
     * on screen whatever the reader does, such as a footer a short page never
     * pushes down. Worth seeing and not worth reporting as a negative stop.
     */
    readonly gained: number;
};

type Ratio = {
    /** `now ÷ was`, or `null` where {@link absent} says why there is none. */
    readonly ratio: number | null;
    /** Why there is no quotient, or `null` where there is one. */
    readonly absent: RatioAbsence | null;
};

type PageReach = {
    readonly treeId: TreeId;
    readonly revision: number;
    /** Page views that began on this revision. Exact, and addable. */
    readonly opened: number;
    /** The same page views as the rollups counted them: once per window each appeared in. */
    readonly appearances: number;
    /** Appearances in excess of openings — the straddle, measured. Never negative. */
    readonly drift: number;
    /** Openings whose reading no rollup has folded yet. The other sign of the same subtraction. */
    readonly pending: number;
    /** `drift ÷ opened`: how generous every distinct count here is. `null` when nothing opened. */
    readonly inflation: number | null;
    /** When the page-view row last moved, or `null` where there is no row. */
    readonly updatedAt: string | null;
    /**
     * The floor the counters give on their own: the largest `views` any one row
     * reports.
     *
     * What a reading had to use as a denominator before there was an exact one,
     * kept so that a deployment can see the difference the join made rather than
     * being told it was wrong. Against an honest sender it sits at or below the
     * openings plus the straddle.
     */
    readonly countedViews: number;
    /**
     * Set where no share can be given, and the reason. `null` where they can.
     */
    readonly silence: ReachSilence | null;
    /**
     * Nobody's visit spanned two windows, so there is nothing to divide out: the
     * estimate and the ceiling are the same number and the shares are exact.
     *
     * False under a silence, and false while any opening is pending.
     */
    readonly exact: boolean;
    /** Every part of the revision, in reading order, as the reading had them. */
    readonly parts: readonly PartReach[];
    /**
     * The parts whose reach could not be reconciled with the openings.
     *
     * Empty is the healthy state. A non-empty list on a deployment whose drift is
     * nought is not a straddle and not a lie: it is node counters older than the
     * column they are being divided by.
     */
    readonly unreconciled: readonly NodeId[];
    /**
     * Page-view rows handed in for another tree or another revision, and ignored.
     *
     * Dividing one revision's counters by another's readers is the mistake that
     * would make every rate here quietly wrong, so this filters rather than
     * trusts its caller — and says how much it dropped, because a caller who
     * passed a whole store's rows and one who passed the wrong revision's look
     * identical from the inside.
     */
    readonly foreign: number;
    /**
     * Rows for this tree and revision beyond the first, where every one after it
     * was ignored.
     *
     * A store keeps one row per revision, so this cannot happen from one read —
     * it happens when a caller concatenates two reads. Adding them is wrong,
     * because the openings are already a total and would double; taking the last
     * is wrong, because it is not the truer one. So the first row stands and the
     * fact is reported.
     */
    readonly duplicated: number;
};

type RegionSide = {
    /** Page views that began here, or `undefined` where the floor withheld the bucket. */
    readonly views: number | undefined;
    /**
     * {@link views} over every view in that window, named and withheld, or
     * `undefined` with it.
     *
     * The denominator is the window's whole total rather than its named buckets,
     * so the shares of a map sum to below 1 by exactly what the floor is holding
     * back. Normalising over the named buckets would make a quiet window's shares
     * add to 1 and read as a complete picture of nothing.
     */
    readonly share: number | undefined;
};

type ComparedRegion = {
    readonly region: ReaderRegion;
    readonly was: RegionSide;
    readonly now: RegionSide;
    readonly movement: RegionMovement;
    /**
     * `now.share − was.share`, or `undefined` where either window withheld the
     * bucket.
     *
     * Signed, and the terms this is summed into are what
     * {@link ReadershipChange.moved} is. A row with no shift is a row that is
     * counted in the unaccounted share instead, which is the same fact said as a
     * bound rather than as a figure.
     */
    readonly shift: number | undefined;
    /**
     * `now.views − was.views`, or `undefined` where either window withheld the
     * bucket.
     *
     * Exact where it is published, and still not a trend: the two windows are two
     * revisions' running totals and were not up for the same length of time.
     */
    readonly change: number | undefined;
};

type UnaccountedShares = {
    readonly was: number;
    readonly now: number;
};

type Arrivals = {
    readonly was: number;
    readonly now: number;
};

type ReaderRegionCount = {
    readonly treeId: TreeId;
    readonly revision: number;
    readonly region: ReaderRegion;
    /** Page views that *began* here, so a longer visit is not a bigger number. */
    readonly views: number;
};

type StoredRegionCount = ReaderRegionCount & {
    readonly audienceId: AudienceId;
    readonly updatedAt: string;
};

interface ReaderRegionStore {
    /**
     * Add views to the buckets they belong in, creating rows that do not exist
     * yet. Additive for the same reason applying a rollup is: every call reports
     * what just arrived rather than what is true so far.
     */
    readonly count: (counts: readonly ReaderRegionCount[], at: string,
    /** The audience the delivery was served under. Omitted is `aud_everyone`. */
    audience?: AudienceId) => Promise<Result<void, ReaderSignalStoreError>>;
    readonly regions: (request?: TallyReadRequest) => Promise<Result<readonly StoredRegionCount[], ReaderSignalStoreError>>;
}

type RegionBucket = {
    readonly region: ReaderRegion;
    readonly views: number;
};

type RegionReading = {
    /** The floor the rows were read at, so a screen can say what it is withholding by. */
    readonly floor: number;
    /**
     * The audience whose arrivals this map is of, or `null` where nothing said.
     *
     * {@link regionReadingFor} names it, because it picked the rows of one
     * audience to build the map from. {@link regionReadingOf} leaves it `null`,
     * because it groups whatever it is handed and a deployment's whole window is
     * a readership rather than one form's.
     *
     * Carried so that a comparison of two maps can refuse a pair of two
     * populations. It is the one thing a readership comparison cannot
     * derive and the one thing that makes it a comparison of like with like.
     *
     * What the map **summed** is the other field, and the two are not the same
     * question: see {@link RegionReading.audiences}.
     */
    readonly audienceId: AudienceId | null;
    /**
     * Every audience the rows this map summed named, deduplicated and in a stable
     * order.
     *
     * The same census `PageReading.audiences` publishes over a window of tallies,
     * and it answers the same question — *what was in the window?* — but it is
     * **not** the same kind of fact. A page reading of two audiences is
     * read as neither, because adding two forms' node counters is one number
     * about two pages. A region map of two audiences is read whole, because
     * adding two forms' arrivals is one number about one deployment's readers:
     * they are people, and a person who arrived arrived once whichever form they
     * were served.
     *
     * So more than one member here is a **measurement and never a fault**: *this
     * map is a sum over two of the forms you serve*. `[]` is a window whose rows
     * named none, which is every window written before the column existed
     * and every one a test builds by hand.
     *
     * It is deliberately not a proof of which form the map is of.
     * {@link RegionReading.audienceId} is that, and it stays `null` on a map read
     * whole however few audiences the rows named — because an `aud_` is a
     * name the host chose for a predicate Loom never sees, and `aud_everyone` is
     * a name for *everybody*. One member means one name was on the rows, not that
     * one population was behind them.
     */
    readonly audiences: readonly AudienceId[];
    /** Buckets large enough to name, most-read first. */
    readonly regions: readonly RegionBucket[];
    /** What was too small to name, as a total that names nowhere. */
    readonly withheld: {
        readonly buckets: number;
        readonly views: number;
    };
    /** Every view in the rows, named or withheld. A reading never loses one. */
    readonly views: number;
};

type RegionReadingOptions = {
    /** Raised above {@link DEFAULT_REGION_FLOOR}; a smaller number is the default.  */
    readonly floor?: number;
};

type ReaderTally = {
    readonly treeId: TreeId;
    readonly revision: number;
    readonly nodeId: NodeId;
    readonly type: PrimitiveType;
    /** Distinct page views that produced any signal at all about this node. */
    readonly views: number;
    /** Distinct page views in which it came into view. The denominator of a funnel. */
    readonly reached: number;
    /**
     * Distinct page views in which a reader used something *inside* this node —
     * pressed a link or button, filled a field, opened or closed a disclosure.
     *
     * The counter regions are reported by, and the only one that needs a signal to
     * say more than which node it is about. A press is filed against the control,
     * and every control in the starter library is an addressed node of its own, so
     * `activations` on a band is nearly always zero and always will be: the band
     * is not the thing anybody pressed. This counts the views whose reader did
     * something under it, at any depth, from the ancestry a delegated signal
     * carries.
     *
     * **Strictly inside.** A button's own `engaged` is 0 while its `activations`
     * is 1; its band's is the other way round. The two never double-count the same
     * node, and a subtree total is the addition.
     *
     * **Zero from a sender that does not walk.** A batch whose delegated signals
     * carry no `within` — synthesised on a server, replayed from a fixture, sent
     * by a host that turned the walk off — adds nothing here, exactly as a batch
     * with no view key adds nothing to `views`.
     */
    readonly engaged: number;
    readonly dwellMs: number;
    readonly activations: number;
    readonly opens: number;
    readonly closes: number;
    /**
     * Times a form inside this node was submitted and the browser let it go.
     *
     * The conversion counter, and the only one that is about a reader finishing
     * rather than a reader looking. It is an occurrence rather than a view count
     * for the same reason `activations` is: a reader who submits twice did two
     * things, and *how many views converted* is a `FunnelPair` ending in
     * `completed`, which is one row and already answerable.
     *
     * Filed against the node the form is — `loom.form` is addressed, so usually
     * the form itself — never the band above it. The band's number is `engaged`,
     * credited from the ancestry the signal carries.
     */
    readonly completions: number;
};

type FunnelEnd = {
    readonly nodeId: NodeId;
    readonly kind: ReaderSignalKind;
};

type FunnelPair = {
    readonly from: FunnelEnd;
    readonly to: FunnelEnd;
};

type FunnelAnswer = {
    readonly treeId: TreeId;
    readonly revision: number;
    readonly pair: FunnelPair;
    /** Views that satisfied `from`. */
    readonly reached: number;
    /** Views that satisfied both. Never greater than `reached`. */
    readonly converted: number;
};

type RollupOptions = {
    /**
     * The funnels this deployment asked for. Absent means none: a pair is a
     * question somebody wrote down, and a rollup does not invent questions.
     */
    readonly pairs?: readonly FunnelPair[];
};

type ReaderSignalParseError = {
    readonly code: "invalid-batch";
    readonly issues: readonly {
        readonly path: string;
        readonly message: string;
    }[];
};

type SilenceMeaning = {
    readonly condition: SilenceCondition;
    readonly subject: SilenceSubject;
    /** The reading that published it, kept so that its own sentence can still be printed. */
    readonly vocabulary: SilenceVocabulary;
};

type StoredTally = ReaderTally & {
    readonly audienceId: AudienceId;
    readonly updatedAt: string;
};

type StoredFunnel = FunnelAnswer & {
    readonly audienceId: AudienceId;
    readonly updatedAt: string;
};

type TallyReadRequest = {
    /** Absent reads every tree the handle can see, which is the scope rule. */
    readonly treeId?: TreeId;
    /**
     * Absent reads every audience.
     *
     * A filter rather than a requirement, on the terms `revision` below is one:
     * comparing two audiences is the point of serving two, so a reading that
     * could not span them would make the comparison the measurement rests on
     * unreadable. Each row names its own audience, so a caller that wants them
     * apart groups rather than summing — and a caller that sums two has asked
     * for one number about two populations.
     */
    readonly audience?: AudienceId;
    /**
     * Absent reads every revision.
     *
     * Almost every question the portal asks is about one revision or about two
     * being compared, and *before versus after a change* is the second of those —
     * so this is a filter rather than a requirement, and a caller comparing
     * revisions reads them all and groups.
     */
    readonly revision?: number;
};

type AppliedCounters = {
    readonly tallies: readonly ReaderTally[];
    readonly funnels: readonly FunnelAnswer[];
    /**
     * The window's page views, per revision, for the counter the exact count
     * is compared against.
     *
     * Optional, and absent is not none: a caller applying counters it
     * composed itself — a backfill, a fixture, a test — has no window to
     * report, and a nought written there would read as *no page views* and
     * make a reading claim the node counters were exact.
     */
    readonly appearances?: readonly RevisionViews[];
};

type AudienceCounters = AppliedCounters & {
    /** The audience this fold was taken over. Omitted is `aud_everyone`. */
    readonly audience?: AudienceId;
};

type ReaderWindowSources = {
    /** The counters, the funnel answers and the door rows. */
    readonly tallies: Pick<ReaderTallyStore, "tallies" | "funnels" | "pageViews">;
    /**
     * Where readers were, which is a second store and an optional one.
     *
     * A deployment that never configured one is not a deployment whose readers
     * were nowhere, so an absent store and an empty map are kept apart all the
     * way to {@link ReaderWindow.regions}.
     */
    readonly regions?: Pick<ReaderRegionStore, "regions">;
};

type ReaderWindow = {
    readonly tallies: readonly StoredTally[];
    readonly funnels: readonly StoredFunnel[];
    readonly pageViews: readonly StoredPageViews[];
    /**
     * The region buckets, or `undefined` where no region store was offered.
     *
     * `undefined` is *nothing here can say* and `[]` is *the store holds none*,
     * which is the distinction this subsystem draws everywhere else it has two
     * such states. A surface that reads them alike reports *we do not
     * know where your readers are* as *you have no readers abroad*.
     */
    readonly regions: readonly StoredRegionCount[] | undefined;
};

type WindowRevision = {
    readonly treeId: TreeId;
    readonly revision: number;
};

type RevisionTrees = {
    /** The tree at that revision, or `undefined` where this source has none. */
    readonly treeFor: (where: WindowRevision) => LoomTree | undefined;
};

type UnjoinedRevision = WindowRevision & {
    readonly cause: UnjoinedCause;
    /** Counter rows left unread, so the cost of not drawing it is a number. */
    readonly tallies: number;
};

type WindowRegionReading = WindowRevision & {
    /**
     * The form these arrivals were served, or `null` where the rows named none.
     *
     * `null` is *no row said*, which is a window written before the column
     * existed and every window a test builds by hand — not `aud_everyone`,
     * which would be asserting a name nobody wrote.
     */
    readonly audienceId: AudienceId | null;
    /** The map itself, floored, as {@link regionReadingOf} reads it. */
    readonly reading: RegionReading;
};

type WindowReadings = {
    /**
     * One reading per page, per revision, per form — which is what one reading is
     * — in a stable order.
     *
     * Never two of one: the key every reading above this refuses to count twice
     * on is the key the window was split by, so a caller may sum across this list
     * on any figure the reading it derives says may be summed.
     */
    readonly pages: readonly PageReading[];
    /** Revisions the rows name that have no reading, in the same order. */
    readonly unjoined: readonly UnjoinedRevision[];
    /**
     * Where the readers were, or `undefined` where no region store was offered.
     *
     * The `undefined` is {@link ReaderWindow.regions}' own, carried rather than
     * collapsed: *we cannot say where your readers are* and *you have no
     * readers abroad* are two sentences, and `[]` holds the second — a window
     * whose store answered with nothing reads as a readership of no views rather
     * than as no readership.
     *
     * **A map here is not held to a tree.** The maps are of arrivals, which need
     * no tree to be read against, so a revision in {@link WindowReadings.unjoined}
     * still has its readers counted. Dropping them would under-report a
     * deployment that has pruned old trees by exactly the readers it has least
     * other record of, and it would make the maps and the readership disagree.
     */
    readonly regions: WindowRegionReadings | undefined;
};

type WindowPair = PageForm & {
    /** The earlier side. Its revision is always below `now`'s. */
    readonly was: PageReading;
    readonly now: PageReading;
    /**
     * Revisions of this form the window holds below `was`, oldest first.
     *
     * Empty for the ordinary case of two. A deployment that has published three
     * times inside one window has an older change in its counters, and this is
     * how a surface says *and one earlier revision* rather than how it reads one:
     * the pair for it is two of {@link WindowReadings.pages} and
     * `readingChangeOf`, which is the same call this makes.
     */
    readonly superseded: readonly number[];
};

type UnpairedForm = PageForm & {
    /** The one reading of it, carried so a surface drawing the page still has it. */
    readonly reading: PageReading;
};

type WindowPairs = {
    /** One per form that has two revisions in the window, in a stable order. */
    readonly pairs: readonly WindowPair[];
    /** The forms that have one, in the same order. */
    readonly unpaired: readonly UnpairedForm[];
    /**
     * Readings handed in twice under one `readingKeyOf`, dropped before pairing.
     *
     * Nought for anything {@link windowReadingsOf} produced, which never holds
     * two readings of one key. It is not nought for a caller that concatenated
     * two windows' readings, and the repeat has to be dropped rather than paired:
     * a form whose latest revision arrived twice would otherwise pair that
     * revision with itself and publish *nothing changed* about a change.
     */
    readonly duplicated: number;
};

type VisibilityObserver = {
    readonly observe: (element: Element) => void;
    readonly disconnect: () => void;
};

type VisibilityEntry = {
    readonly target: Element;
    readonly visible: boolean;
};

type ReaderSignalTypes = readonly string[] | {
    readonly [Kind in ReaderSignalKind]?: readonly string[];
};

type ReaderSignalOptions = {
    /** Called with every batch. A throw or rejection here is contained and never reaches the page. */
    readonly send?: (batch: ReaderSignalBatch) => void | Promise<void>;
    /** Which kinds to broadcast. Every kind when absent. */
    readonly kinds?: readonly ReaderSignalKind[];
    /**
     * Which primitive types to broadcast about. Every addressed type when absent.
     *
     * A list applies to every kind. An object sets it per kind — time on screen
     * for sections, activations for links — and a kind it does not name is
     * reported for every type, exactly as if `types` were absent for that kind.
     * Whether a kind is reported at all is still `kinds`.
     */
    readonly types?: ReaderSignalTypes;
    /** How often a batch is delivered. Five seconds when absent. */
    readonly flushEveryMs?: number;
    /**
     * How the broadcaster learns what is on screen. The browser's
     * `IntersectionObserver` when absent; a test passes its own.
     */
    readonly observeVisibility?: ObserveVisibility;
    /**
     * Whether a delegated signal carries the addressed nodes it happened inside.
     * On when absent.
     *
     * `activated` and `disclosed` are filed against the control a reader aimed
     * at, which is an addressed node of its own — so without the ancestry a
     * deployment can report which button was pressed and never which region it
     * was in. Off is for a host that reports on controls only and would rather
     * not carry the walk in every batch.
     */
    readonly within?: boolean;
    /** The clock. `Date.now` when absent. */
    readonly now?: () => number;
    /**
     * Where the view key's randomness comes from. The browser's
     * `crypto.getRandomValues` when absent; a test passes its own so it can name
     * the key it expects.
     */
    readonly random?: RandomBytes;
};

type ReaderSignalBroadcast = {
    /** Deliver whatever has been gathered, now. */
    readonly flush: () => void;
    /** Deliver what is left and stop observing. Safe to call twice. */
    readonly stop: () => void;
};

type ReaderSignalBroadcastError = {
    /** The root carries no tree id or revision — the page was not rendered with `addressed: true`. */
    readonly code: "unaddressed";
    readonly detail: string;
};

type DeliverOptions = {
    /** Where to post. {@link DEFAULT_READER_SIGNAL_PATH} when absent. */
    readonly url?: string;
    /** The browser's, when absent. A test passes its own. */
    readonly beacon?: SendBeacon | null;
    /** `fetch` with `keepalive`, when absent. */
    readonly post?: PostBatch;
};

type CalibrationScore = {
    readonly judged: number;
    readonly survived: number;
    /** null when nothing was judged — zero out of zero is not zero. */
    readonly observedRate: number | null;
    readonly meanConfidence: number | null;
    /**
     * `meanConfidence - observedRate`. Positive means the model claimed more than
     * it delivered. null when there is nothing to compare.
     */
    readonly gap: number | null;
};

type ConfidenceBucket = CalibrationScore & {
    readonly lower: number;
    readonly upper: number;
};

type CalibrationReport = {
    readonly overall: CalibrationScore;
    readonly buckets: readonly ConfidenceBucket[];
    /**
     * The same claims again, split by the policy that judged each one. Every
     * judged proposal appears in exactly one segment, so the segments sum to
     * `overall` — the split is a partition, not a sample.
     *
     * Ordered by policy name, with the unrecorded segment last, so a reader
     * comparing two windows is comparing rows in the same order.
     */
    readonly byPolicy: readonly PolicyCalibration[];
    /** Proposals that produced no verdict, by why. Never in a denominator. */
    readonly unjudged: Readonly<Record<UnjudgedReason, number>>;
    /**
     * Records the fold could not attribute to a proposal, carried through rather
     * than dropped — the same reason `EpisodeFold` returns them. A rate computed
     * over a window that silently lost records is a rate over a denominator it
     * changed without saying so.
     */
    readonly unattributed: number;
    /**
     * Proposals the runtime authored rather than a model — the inverse behind a
     * revert, say. Segmented rather than dropped: they carry a confidence because
     * every proposal does, but nobody graded it, so scoring them would measure the
     * constant the runtime stamps. Reporting the count keeps that visible instead
     * of leaving a reader to wonder where the undos went.
     */
    readonly runtimeAuthored: number;
};

type EpisodeFailure = TelemetryFailure & {
    readonly stage: FailureStage;
};

type ProposalEpisode = {
    readonly proposalId: ProposalId;
    /** Set when this proposal replaced one the Gate refused. */
    readonly repairOf?: ProposalId;
    readonly provenance: Provenance;
    readonly rationale: string;
    readonly delta: TreeDelta;
    readonly proposedAt: string;
    readonly assessment?: AssessmentSummary;
    readonly disposition?: Disposition;
    /** The Gate held it and custody succeeded, so a human was asked. */
    readonly held: boolean;
    /** A refusal that was handed back for one more attempt. */
    readonly repairRequested: boolean;
    readonly answer?: EpisodeAnswer;
    /**
     * Who answered. Distinct from `provenance.actor`, which is who asked — a hold
     * exists to put a second person in the way of a change, and an episode that
     * showed only the asker would make the two look like one.
     */
    readonly answeredBy?: string;
    /** Applied in memory. Present without `committedRevision` means it did not persist. */
    readonly appliedRevision?: number;
    readonly committedRevision?: number;
    readonly failure?: EpisodeFailure;
    readonly settledAt?: string;
};

type EpisodeResolution = {
    readonly kind: "committed";
    readonly proposalId: ProposalId;
    readonly revision: number;
} | {
    readonly kind: "refused";
    readonly proposalId: ProposalId;
} | {
    readonly kind: "awaiting-answer";
    readonly proposalId: ProposalId;
} | {
    readonly kind: "discarded";
    readonly proposalId: ProposalId;
} | {
    readonly kind: "not-interpreted";
    readonly failure: EpisodeFailure;
} | {
    readonly kind: "not-writable";
    readonly failure: EpisodeFailure;
} | {
    readonly kind: "failed";
    readonly proposalId: ProposalId;
    readonly failure: EpisodeFailure;
}
/** Nothing in this window settled it — still in flight, or the page ends mid-episode. */
 | {
    readonly kind: "open";
};

type IntentEpisode = {
    readonly intentId: IntentId;
    readonly treeId: TreeId;
    /** Absent when the window opened after the intent was received. */
    readonly intent?: IntentSummary;
    /**
     * The policy this intent was last resolved to be judged under. Absent when
     * the window opened after resolution, or when the records predate it.
     *
     * "Last" matters for a proposal that was held and later confirmed: the Gate
     * resolves again on the second look, so a host that narrowed its policy in
     * between shows two resolutions and this keeps the one that decided the
     * outcome. Each proposal's disposition carries the policy that judged that
     * proposal, which is the finer-grained truth.
     */
    readonly policyId?: string;
    readonly startedAt: string;
    readonly proposals: readonly ProposalEpisode[];
    readonly resolution: EpisodeResolution;
};

type EpisodeFold = {
    readonly episodes: readonly IntentEpisode[];
    /**
     * Records that name a proposal this window never saw proposed. Returned
     * rather than discarded: a fold that quietly dropped them would report a
     * refusal rate over a denominator it had silently changed.
     */
    readonly unattributed: readonly RecordedTelemetry[];
};

type EpisodeTally = {
    readonly episodes: number;
    readonly proposals: number;
    /** Proposals the Gate would not apply on its own. */
    readonly held: number;
    /** Proposals made to replace one the Gate refused. */
    readonly repairs: number;
    /**
     * Every kind, including the ones that did not happen. A resolution absent from
     * this map and one that occurred zero times are different claims, and only one
     * of them is true.
     */
    readonly byResolution: Readonly<Record<EpisodeResolutionKind, number>>;
};

type TelemetryFailure = {
    readonly code: string;
    readonly detail: string;
};

type IntentSummary = {
    readonly intentId: IntentId;
    readonly origin: IntentOrigin;
    readonly actor?: string;
    readonly baseRevision: number;
    readonly scopeNodeId?: NodeId;
    readonly utteranceLength: number;
    readonly observedAt: string;
};

type AssessmentSummary = {
    readonly proposalId: ProposalId;
    readonly stakes: StakeLevel;
    readonly reversible: boolean;
    readonly operationCount: number;
    readonly insertedNodeCount: number;
    readonly removedNodeCount: number;
    readonly movedNodeCount: number;
    readonly configuredNodeCount: number;
    readonly touchedPrimitiveTypes: readonly PrimitiveType[];
    /** Absent on a record written before the field existed, never defaulted. */
    readonly removedPrimitiveTypes?: readonly PrimitiveType[];
    readonly relocatedPrimitiveTypes?: readonly PrimitiveType[];
    readonly relocatedNodeCount?: number;
    readonly shallowestAffectedDepth: number;
    /** Absent on a record written before the field existed, never defaulted. */
    readonly affectedNodeCount?: number;
    /** Absent on a record written before the field existed, never defaulted. */
    readonly configuredPropKeys?: readonly string[];
    readonly retainedNodeCount: number;
    readonly irreversibilityReasons: readonly string[];
    /** Absent when no out-of-tree reason fired, and before the field existed. */
    readonly outOfTreeEffectTypes?: readonly PrimitiveType[];
    /** Absent on a record written before the field existed, never defaulted. */
    readonly stakeFactorCodes?: readonly StakeFactorCode[];
};

